// Conversation Atlas: a self-updating map of a long Claude Code session in a docked pane.
//
// Three feeds write OBSERVATIONS, none of them intent:
//   engine events   tool calls, files, tests, commits, subagents, questions   (no tokens)
//   your prompts    the first request, side-trip / return / decision wording (no tokens)
//   Claude          one short `observe` call when the topic moves or a decision lands
// INTENT (goal, detour, return, next step, marks) changes only when you press a pane
// button or type /atlas. See types/index.d.ts and hooks/model.ts.

import { type EngineInterface, type Register, type Timer, update } from 'claude-code'

import type { AtlasMode, AtlasScanState, AtlasSnapshot, AtlasTrailView, AtlasView } from '../types'
import { askedQuestions, classify, planTitle, posix } from './activity'
import type { LiveRow } from './live'
import { expectedReportPath, handoffStart, parseHandoffReport, reportChanged, reportFingerprint } from './delegation'
import {
  addCheckpoint,
  addQuestion,
  clearFresh,
  closeUnverifiedHandoffs,
  clip,
  confirmSuggestion,
  dismissSuggestion,
  emptySnapshot,
  endActivity,
  hydrate,
  intentLine,
  mark,
  observe,
  type ObserveReport,
  offerResume,
  openQuestions,
  promoteDetour,
  reportHandoff,
  resolveQuestions,
  reportMarker,
  returnFromDetour,
  sentences,
  setGoal,
  setItemStatus,
  toggleDecisionWeight,
  setHandoffTaskId,
  setNextStep,
  startActivity,
  startHandoff,
  startDetour,
  startTurn,
  summary,
  takeContext,
  upgrade,
  touchFile,
  addDecision,
  addDetourFinding,
  adoptRecall,
  hasReplaceableContent,
  recoverFull,
  recordDecision,
  setRecall,
} from './model'
import { applyMap, MAP_PROMPT, parseMap, replay, type ScanRow } from './scan'
import {
  ATLAS_DIR,
  fromAtlasFile,
  fromAtlasFullFile,
  atlasFullFileError,
  mergeRecall,
  pickRecallEntries,
  safeName,
  saveFile,
  sessionsToDelete,
  type AtlasFullRecall,
} from './recall'
import { type Action, oneLine, pane, TONES } from './view'
import type { Surface } from './ui/shared'

const PLUGIN = 'conversation-atlas'
const SNAP = { plugin: 'conversation-atlas', key: 'snapshot' } as const
const VIEW = { plugin: 'conversation-atlas', key: 'view' } as const
const SCAN = { plugin: 'conversation-atlas', key: 'scanning' } as const
const PANE = 'atlas'
const TOOL = 'mcp__conversation-atlas__observe'
const TRAIL_VIEW_STORE = 'trail-view'
const FLASH_MS = 4_000
const SAVE_MS = 2_000
const KEEP_SESSIONS = 12
const SCAN_RESULT_MS = 4_000
const MODE = { plugin: 'conversation-atlas', key: 'mode' } as const
const DEFAULT_VIEW: AtlasViewState = {
  setup: false,
  tab: 'map',
  refs: {},
  nextRef: 1,
  editingGoal: false,
  legend: false,
  legendHowTo: false,
  popup: null,
  popupScroll: 0,
  legendScroll: 0,
  scroll: 0,
  trailNewest: true,
  trailView: 'story',
  expanded: null,
  expandedScroll: 0,
  fullConfirm: null,
  hidden: [],
  settingsPage: 0,
}

type AtlasViewState = AtlasView & { hidden: string[]; settingsPage: number }

const RULES = `# Conversation Atlas
 A side pane maps this session for the user. Keep it accurate with ${TOOL}: at the end of a turn where the topic moved, a decision was reached,
 a question opened or closed, or a milestone landed, call it once with only the fields that changed (short phrases, at most 6 words for a topic).
 Call ${TOOL} in parallel with another tool call already needed in this response; never alone in a final round.
 If none is needed, skip it and report it on the next tool-using turn.
 shift: "same" (refining the current topic), "subtopic" (going deeper), "sibling" (next part of the same work),
 "possible-detour" (a side trip away from the user's goal), "return" (back to earlier work; name that topic). Skip it on trivial turns.
 Report goal whenever the user's apparent overall aim changes; Atlas shows that as an observation, never as a confirmed goal.
 It records observations only: never say the user's confirmed goal changed and never treat a detour as accepted;
 the user confirms goals, detours and returns in the pane.
 Do not mention the atlas to the user.`

type Raw = Record<string, unknown>

function taskIdOf(value: unknown): string | null {
  if (!value || typeof value !== 'object') return null
  const record = value as Raw
  for (const key of ['taskId', 'task_id', 'task-id']) {
    if (typeof record[key] === 'string' && record[key]) return record[key] as string
  }
  for (const key of ['result', 'task', 'metadata']) {
    const nested = taskIdOf(record[key])
    if (nested) return nested
  }
  return null
}

// A Client's props must be plain JSON: no undefined fields.
function plain(rows: LiveRow[]): LiveRow[] {
  const clean = (segs: LiveRow['segs']) => segs.map(s => Object.fromEntries(Object.entries(s).filter(([, v]) => v !== undefined && v !== false)) as LiveRow['segs'][number])
  return rows.map(r => (r.right?.length ? { segs: clean(r.segs), right: clean(r.right) } : { segs: clean(r.segs) }))
}

let sid = ''
let root = ''
let flashTimer: Timer | null = null
let lastSaved: AtlasSnapshot | undefined
let observedThisTurn = false
let activitySeq = 0
type ScrollBounds = {
  bodyRows: number
  maxScroll: number
  maxPopupScroll: number
  maxExpandedScroll: number
  maxLegendScroll: number
}
const EMPTY_BOUNDS: ScrollBounds = {
  bodyRows: 0, maxScroll: 0, maxPopupScroll: 0, maxExpandedScroll: 0, maxLegendScroll: 0,
}
// Each surface owns the bounds measured by its last draw.
const surfaceBounds = new Map<Surface, ScrollBounds>()
const drawnSurfaces = new Set<Surface>()

function wheelBounds(bodyRows: number): ScrollBounds {
  const bounds = [...surfaceBounds.values()]
  const matches = bounds.filter(bound => bound.bodyRows === bodyRows)
  if (matches.length === 1) return matches[0] ?? EMPTY_BOUNDS
  // Wheel events have no surface identity. Ambiguous sizes must not impose
  // the smaller surface's bounds on the larger one; each draw still clamps.
  return bounds.reduce((largest, bound) => ({
    bodyRows,
    maxScroll: Math.max(largest.maxScroll, bound.maxScroll),
    maxPopupScroll: Math.max(largest.maxPopupScroll, bound.maxPopupScroll),
    maxExpandedScroll: Math.max(largest.maxExpandedScroll, bound.maxExpandedScroll),
    maxLegendScroll: Math.max(largest.maxLegendScroll, bound.maxLegendScroll),
  }), EMPTY_BOUNDS)
}
let scanOnLaunch: 'off' | 'engine' | 'claude' = 'engine'
let configuredMode: AtlasMode = 'claude'
let observerToolRegistered = false
const agentNames = new Map<string, string>()

// ------------------------------------------------------------------ state

async function snap($: EngineInterface): Promise<AtlasSnapshot | undefined> {
  const value = (await $.state.get(SNAP)).value
  return value ? upgrade(value) : value
}

function isScanState(value: unknown): value is AtlasScanState {
  if (!value || typeof value !== 'object') return false
  const scan = value as Partial<AtlasScanState>
  return typeof scan.active === 'boolean' && typeof scan.startedAt === 'number' && (typeof scan.result === 'string' || scan.result === null) && typeof scan.resultAt === 'number'
}

async function scanState($: EngineInterface): Promise<AtlasScanState> {
  const value = (await $.state.get(SCAN)).value
  return isScanState(value) ? value : EMPTY_SCAN
}

async function ensureScanState($: EngineInterface): Promise<void> {
  await update($, SCAN, cur => isScanState(cur) ? cur : EMPTY_SCAN)
}

async function identity($: EngineInterface): Promise<{ sid: string; root: string }> {
  const [id, r] = await Promise.all([$.session.id(), $.session.root()])
  return { sid: id, root: posix(r) }
}

async function edit($: EngineInterface, fn: (s: AtlasSnapshot, now: number) => AtlasSnapshot): Promise<AtlasSnapshot> {
  const now = await $.clock.now()
  const before = await snap($)
  const out = await update($, SNAP, cur => fn(cur && cur.sessionId === sid ? upgrade(cur) : emptySnapshot(sid, root, now), now))
  if (out.fresh.length && out.fresh.join() !== (before?.fresh ?? []).join()) scheduleUnflash($)
  return out
}

function scheduleUnflash($: EngineInterface): void {
  flashTimer?.cancel()
  flashTimer = $.clock.after(FLASH_MS, () => {
    flashTimer = null
    void edit($, s => clearFresh(s))
  })
}

async function setView($: EngineInterface, fn: (v: AtlasViewState) => AtlasViewState): Promise<void> {
  await update($, VIEW, cur => fn({ ...DEFAULT_VIEW, ...(cur ?? {}) }))
}

async function trailViewChoice($: EngineInterface): Promise<AtlasTrailView> {
  const value = await $.store.get(TRAIL_VIEW_STORE)
  if (!value || typeof value !== 'object') return 'story'
  const view = (value as { view?: unknown }).view
  return view === 'log' || view === 'story' ? view : 'story'
}

async function isLegendOpen($: EngineInterface): Promise<boolean> {
  const value = (await $.state.get(VIEW)).value
  return Boolean(value && typeof value === 'object' && (value as Partial<AtlasView>).legend)
}

type SetupChoice = { observer: AtlasMode; at: number }

function isMode(value: unknown): value is AtlasMode {
  return value === 'claude' || value === 'engine'
}

async function setupChoice($: EngineInterface): Promise<SetupChoice | undefined> {
  const value = await $.store.get('setup')
  if (!value || typeof value !== 'object') return undefined
  const raw = value as Raw
  return isMode(raw.observer) && typeof raw.at === 'number' ? { observer: raw.observer, at: raw.at } : undefined
}

// Before consent, engine-only is always the effective mode. The userConfig value
// is only the setup screen's default; a stored choice is authoritative thereafter.
async function syncMode($: EngineInterface): Promise<AtlasMode> {
  const choice = await setupChoice($)
  const mode: AtlasMode = choice?.observer ?? 'engine'
  await $.state.set(MODE, mode)
  const trailView = await trailViewChoice($)
  const savedView = await $.store.get(TRAIL_VIEW_STORE)
  const hidden = savedView && typeof savedView === 'object' && Array.isArray((savedView as Raw).hidden)
    ? (savedView as { hidden: unknown[] }).hidden.filter((type): type is string => type === 'b' || type === 'h')
    : []
  await setView($, v => ({ ...v, setup: !choice, trailView, hidden }))
  return mode
}

async function modeOf($: EngineInterface): Promise<AtlasMode> {
  const value = (await $.state.get(MODE)).value
  if (isMode(value)) return value
  const choice = await setupChoice($)
  return choice?.observer ?? 'engine'
}

const OBSERVER_TOOL = {
  name: 'observe',
  description: 'Record what moved in this session on the Conversation Atlas pane: topic and shift, decisions, open or resolved questions, the next step, a milestone. Observations only; the user confirms intent.',
  inputSchema: {
    type: 'object',
    properties: {
      topic: { type: 'string', description: 'What the conversation is about now, at most 6 words' },
      shift: { type: 'string', enum: ['same', 'subtopic', 'sibling', 'possible-detour', 'return'] },
      why: { type: 'string', description: 'One line, for possible-detour or return' },
      decisions: { type: 'array', items: { type: 'string' }, description: 'Conclusions reached this turn' },
      questions: { type: 'array', items: { type: 'string' }, description: 'Questions left open for the user' },
      resolved: { type: 'array', items: { type: 'string' }, description: 'Earlier open questions now answered' },
      next: { type: 'string', description: 'The most useful next step to resume from' },
      checkpoint: { type: 'string', description: 'A milestone just reached, a few words' },
      goal: { type: 'string', description: 'The apparent overall aim when it changes; Atlas records it as an observation and never treats it as confirmed' },
    },
  },
} as const

async function registerObserverTool($: EngineInterface): Promise<void> {
  if (observerToolRegistered) return
  await $.tool.register(OBSERVER_TOOL)
  observerToolRegistered = true
}

async function chooseObserver($: EngineInterface, mode: AtlasMode): Promise<void> {
  const at = await $.clock.now()
  await $.store.set('setup', { observer: mode, at })
  await $.state.set(MODE, mode)
  await setView($, v => ({ ...v, setup: false, popup: null, popupScroll: 0, scroll: 0 }))
  if (mode === 'claude') await registerObserverTool($)
}

// Binds the snapshot to the live session: same id keeps it (a hot reload), a saved one is
// restored (a resume), otherwise a fresh map that offers the project's last goal.
async function bind($: EngineInterface): Promise<void> {
  const who = await identity($)
  sid = who.sid
  root = who.root
  await ensureScanState($)
  const mode = await syncMode($)
  const cur = await snap($)
  if (cur?.sessionId === sid) return
  const now = await $.clock.now()
  const saved = await $.store.get(`session:${sid}`)
  let next = saved ? hydrate(saved, sid, root, now) : emptySnapshot(sid, root, now)
  if (!saved) {
    const previous = (await $.store.get(`project:${root}`)) as (ReturnType<typeof summary> & { sessionId?: string }) | undefined
    if (previous && previous.sessionId !== sid) next = offerResume(next, previous, now)
  }
  // Joined a thread that already has history (installed or reloaded mid-session, resumed
  // without a save): replay it for free so the map starts where the conversation is.
  const rows = scanOnLaunch === 'off' || next.scanned !== 'none' ? [] : await history($)
  if (rows.length) next = { ...replay(next, rows, now), scanned: 'engine' }
  await $.state.set(SNAP, next)
  if (rows.length > 2 && scanOnLaunch === 'claude' && mode === 'claude') void mapWithClaude($).catch(() => undefined)
  lastSaved = saved ? next : undefined
  void loadRecall($).catch(() => undefined)
}

async function history($: EngineInterface): Promise<ScanRow[]> {
  try {
    const rows = await $.session.messages()
    return Array.isArray(rows) ? (rows as ScanRow[]) : []
  } catch {
    return []
  }
}

// One forked request over the session's own transcript (served mostly from the prompt
// cache): topics, decisions, open questions and a next step, added as observations.
async function mapWithClaude($: EngineInterface): Promise<string> {
  const current = await scanState($)
  if (current.active) return 'A scan is already running.'
  const startedAt = await $.clock.now()
  await update($, SCAN, cur => {
    const previous = isScanState(cur) ? cur : EMPTY_SCAN
    return previous.active ? previous : { active: true, startedAt, result: null, resultAt: 0 }
  })
  scanResultTimer?.cancel()
  scanResultTimer = null
  let outcome = ''
  try {
    $.ui.toast('Atlas: mapping the conversation so far…')
    const reply = await $.model.fork({ prompt: MAP_PROMPT })
    if (!reply.isAnswered) outcome = `Atlas could not map the conversation: ${reply.reason}`
    else {
      const map = parseMap(reply.text)
      if (!map) outcome = 'Atlas could not read the map Claude returned.'
      else {
        await edit($, (s, now) => ({ ...applyMap(s, map, now), scanned: 'claude' }))
        outcome = `Mapped ${map.topics.length} topics, ${map.rest.decisions?.length ?? 0} decisions, ${map.rest.questions?.length ?? 0} open questions. All are observations: confirm what is true in the Open tab.`
      }
    }
  } catch (err) {
    outcome = `Atlas could not map the conversation: ${err instanceof Error ? err.message : String(err)}`
  } finally {
    const result = outcome || 'Atlas could not map the conversation.'
    const resultAt = await $.clock.now()
    await update($, SCAN, cur => {
      const previous = isScanState(cur) ? cur : EMPTY_SCAN
      return { ...previous, active: false, startedAt, result, resultAt }
    })
    scanResultTimer = $.clock.after(SCAN_RESULT_MS, () => {
      scanResultTimer = null
      void update($, SCAN, cur => {
        if (!isScanState(cur) || cur.resultAt !== resultAt) return isScanState(cur) ? cur : EMPTY_SCAN
        return { ...cur, result: null, resultAt: 0 }
      }).catch(() => undefined)
    })
    $.ui.toast(result)
  }
  return outcome || 'Atlas could not map the conversation.'
}

// Earlier Atlas save files from this project's .claude folder.
async function loadRecall($: EngineInterface): Promise<number> {
  const found: Parameters<typeof mergeRecall>[0] = []
  const path = `${root}/${ATLAS_DIR}`
  let entries: { name: string; kind: string }[] = []
  try {
    entries = await $.fs.list(path)
  } catch {
    entries = []
  }
  const candidates = entries.filter(x => x.kind === 'file' && x.name.endsWith('.json'))
  const dated = await Promise.all(candidates.map(async entry => {
    try {
      const stat = await $.fs.stat(`${path}/${entry.name}`)
      return { name: entry.name, mtimeMs: stat.mtimeMs }
    } catch {
      return { name: entry.name }
    }
  }))
  for (const entry of pickRecallEntries(dated, 80)) {
    try {
      const text = await $.fs.read(`${path}/${entry.name}`)
      const hit = typeof text === 'string' ? fromAtlasFile(text, root) : null
      if (hit) found.push(hit)
    } catch {
      continue
    }
  }
  const recall = mergeRecall(found)
  await edit($, s => setRecall(s, recall))
  return recall.filter(r => r.sessionId !== sid).length
}

async function readFullRecall(
  $: EngineInterface,
  recall: { source: string; sessionId: string },
): Promise<{ source: AtlasFullRecall | null; error: string | null }> {
  if (recall.source !== 'atlas') return { source: null, error: 'full recovery is available only for Atlas save files' }
  try {
    const text = await $.fs.read(`${root}/${ATLAS_DIR}/${safeName(recall.sessionId)}.json`)
    if (typeof text !== 'string') return { source: null, error: 'save file is not text' }
    const source = fromAtlasFullFile(text, root)
    if (source) return { source, error: null }
    return { source: null, error: atlasFullFileError(text, root) ?? 'invalid Atlas save' }
  } catch {
    return { source: null, error: 'could not read the save file' }
  }
}

// External agents cannot send a turn notification back through the engine. A
// report file is the deliberately visible bridge; malformed or still-written
// files are ignored until a later turn/timer check.
async function checkHandoffReports($: EngineInterface): Promise<void> {
  const current = await snap($)
  const open = current?.handoffs.filter(h => h.status === 'open' && h.reportPath) ?? []
  if (!open.length) return
  for (const handoff of open) {
    let raw: unknown
    try {
      raw = await $.fs.read(handoff.reportPath as string)
    } catch {
      continue
    }
    if (!reportChanged(handoff.reportFingerprint, raw)) continue
    const report = parseHandoffReport(raw)
    if (!report) continue
    await edit($, (s, now) => {
      let next = reportHandoff(s, report.summary, now, handoff.agent, handoff.id, report.tests, report.files)
      for (const file of report.files) next = touchFile(next, file, 'write', now, handoff.agent)
      return next
    })
  }
}

async function ensureBound($: EngineInterface): Promise<void> {
  await setup($)
  if (!sid || (await $.session.id()) !== sid) await bind($)
}

async function save($: EngineInterface): Promise<void> {
  const s = await snap($)
  if (!s || s === lastSaved || s.sessionId !== sid) return
  lastSaved = s
  const savedAt = await $.clock.now()
  await $.store.set(`session:${s.sessionId}`, { ...s, fresh: [], pendingContext: [], savedAt })
  await $.store.set(`project:${s.root}`, { ...summary(s), sessionId: s.sessionId })
  // The project-local copy, so a later session (or another tool) finds this trail on disk.
  if (s.goal || s.topics.length || s.decisions.length) await $.fs.write(`${s.root}/${ATLAS_DIR}/${safeName(s.sessionId)}.json`, saveFile(s, savedAt))
  const keys = (await $.store.keys()).filter(k => k.startsWith('session:'))
  const entries = await Promise.all(keys.map(async key => ({ key, value: await $.store.get(key) })))
  const stored = entries.map(entry => {
    const value = entry.value
    const savedAt = value && typeof value === 'object' && typeof (value as { savedAt?: unknown }).savedAt === 'number'
      ? (value as { savedAt: number }).savedAt
      : 0
    return { key: entry.key, savedAt }
  })
  for (const old of sessionsToDelete(stored, `session:${s.sessionId}`, KEEP_SESSIONS)) await $.store.delete(old)
}

async function openPane($: EngineInterface, focus: boolean): Promise<boolean> {
  const opened = await $.ui.open({ id: PANE, title: 'Atlas', columns: 46, ...(focus ? { focus: true } : {}) })
  return opened.isPlaced
}

// ------------------------------------------------------------------ actions (the only intent writers)

async function act($: EngineInterface, a: Action, surface: Surface): Promise<void> {
  const { maxScroll, maxPopupScroll, maxExpandedScroll, maxLegendScroll } = surfaceBounds.get(surface) ?? EMPTY_BOUNDS
  switch (a.type) {
    case 'tab':
      return setView($, v => ({ ...v, tab: a.tab, scroll: 0, legend: false, popup: null, popupScroll: 0, expanded: null, expandedScroll: 0 }))
    case 'legend':
      return setView($, v => ({ ...v, legend: !v.legend, legendScroll: 0, popup: null, popupScroll: 0 }))
    case 'legend-howto':
      return setView($, v => ({ ...v, legendHowTo: !v.legendHowTo, legendScroll: 0, popup: null, popupScroll: 0 }))
    case 'dismiss-goal-alt':
      // Dismissals belong to the session view and survive changes to the confirmed goal.
      return setView($, v => ({
        ...v,
        dismissedGoalAlts: [...(v.dismissedGoalAlts ?? []).filter(text => text !== clip(a.text, 140)), clip(a.text, 140)].slice(-20),
        popup: null,
        popupScroll: 0,
      }))
    case 'open-setup':
      return setView($, v => ({ ...v, setup: true, legend: false, popup: null, popupScroll: 0, scroll: 0 }))
    case 'set-observer':
      await chooseObserver($, a.mode)
      return
    case 'toggle-observer': {
      const current = await modeOf($)
      await chooseObserver($, current === 'claude' ? 'engine' : 'claude')
      return
    }
    case 'popup':
      return setView($, v => ({
        ...v,
        legend: false,
        expanded: null,
        expandedScroll: 0,
        popup: v.popup?.kind === a.popup.kind && v.popup.id === a.popup.id ? null : a.popup,
        popupScroll: 0,
        settingsPage: a.popup.kind === 'trail-view' ? 0 : v.settingsPage,
      }))
    case 'trail-settings-page':
      return setView($, v => ({ ...v, settingsPage: Math.max(0, Math.min(2, a.page)), popupScroll: 0 }))
    case 'trail-filter': {
      const current = (await $.state.get(VIEW)).value as AtlasViewState | undefined
      const hidden = (current?.hidden ?? []).includes(a.filter)
        ? (current?.hidden ?? []).filter(type => type !== a.filter)
        : [...(current?.hidden ?? []), a.filter]
      await $.store.set(TRAIL_VIEW_STORE, { view: current?.trailView ?? 'story', hidden, at: await $.clock.now() })
      return setView($, v => ({ ...v, hidden }))
    }
    case 'popup-scroll':
      return setView($, v => ({ ...v, popupScroll: Math.max(0, Math.min(maxPopupScroll, v.popupScroll + a.by)) }))
    case 'expanded-scroll':
      return setView($, v => ({ ...v, expandedScroll: Math.max(0, Math.min(maxExpandedScroll, v.expandedScroll + a.by)) }))
    case 'scroll':
      if (await isLegendOpen($)) return setView($, v => ({ ...v, legendScroll: Math.max(0, Math.min(maxLegendScroll, v.legendScroll + a.by)) }))
      return setView($, v => ({ ...v, scroll: Math.max(0, Math.min(maxScroll, v.scroll + a.by)), popup: null, popupScroll: 0 }))
    case 'scroll-to':
      return setView($, v => ({ ...v, scroll: Math.max(0, Math.min(maxScroll, a.at)), popup: null, popupScroll: 0 }))
    case 'trail-sort':
      return setView($, v => ({ ...v, trailNewest: !v.trailNewest, popupScroll: 0, expanded: null, expandedScroll: 0 }))
    case 'trail-view-set':
    case 'trail-view': {
      const at = await $.clock.now()
      const current = await $.store.get(TRAIL_VIEW_STORE)
      const hidden = current && typeof current === 'object' && Array.isArray((current as Raw).hidden)
        ? (current as { hidden: string[] }).hidden
        : []
      await $.store.set(TRAIL_VIEW_STORE, { view: a.view, hidden, at })
      return setView($, v => ({
        ...v,
        trailView: a.view,
        ...(a.type === 'trail-view' ? { popup: null } : {}),
        popupScroll: 0,
        expanded: null,
        expandedScroll: 0,
      }))
    }
    case 'expand':
      return setView($, v => ({ ...v, expanded: v.expanded === a.id ? null : a.id, expandedScroll: 0, popup: null, popupScroll: 0 }))
    case 'exclude':
      await edit($, (s, now) => setItemStatus(s, a.id, 'excluded', now))
      await setView($, v => ({ ...v, popup: null, popupScroll: 0 }))
      return
    case 'scan': {
      const rows = await history($)
      if ((await snap($))?.scanned === 'none' && rows.length) await edit($, (s, now) => ({ ...replay(s, rows, now), scanned: 'engine' }))
      await mapWithClaude($)
      await setView($, v => ({ ...v, popup: null, popupScroll: 0 }))
      return
    }
    case 'adopt':
      await edit($, (s, now) => adoptRecall(s, a.id, now))
      await setView($, v => ({ ...v, popup: null, popupScroll: 0, fullConfirm: null }))
      $.ui.toast('Resumed: the earlier goal, next step and decisions are back')
      return
    case 'adopt-full': {
      const current = await snap($)
      const recall = current?.recall.find(candidate => candidate.id === a.id)
      if (!current || !recall || recall.source !== 'atlas') return
      const view = (await $.state.get(VIEW)).value as AtlasView | undefined
      if (hasReplaceableContent(current) && view?.fullConfirm !== a.id) {
        await setView($, v => ({ ...v, fullConfirm: a.id, popup: null, popupScroll: 0 }))
        return
      }
      const loaded = await readFullRecall($, recall)
      const source = loaded.source
      if (!source) {
        $.ui.toast(`Can't load that save: ${loaded.error ?? 'invalid Atlas save'}`)
        return
      }
      await edit($, (s, now) => recoverFull(s, source, now))
      await setView($, v => ({ ...v, popup: null, popupScroll: 0, fullConfirm: null }))
      $.ui.toast('Loaded the full saved map; the earlier session is now this map')
      return
    }
    case 'attach': {
      // A chip in the draft is the only way Atlas text reaches Claude from the pane.
      let n = 1
      await setView($, v => {
        n = v.nextRef
        return { ...v, refs: { ...v.refs, [String(n)]: a.ref }, nextRef: n + 1, popup: null, popupScroll: 0 }
      })
      const chip = ` [Atlas #${n}: ${a.ref.kind.toLowerCase()} "${clip(a.ref.text, 28)}"] `
      const filled = await $.prompt.fill({ text: chip, mode: 'insert' })
      $.ui.toast(filled.isFilled ? `Added to your message as Atlas #${n}; delete the chip to not send it` : 'Atlas: could not add to the message (a dialog is open?)')
      return
    }
    case 'edit-goal':
      return setView($, v => ({ ...v, editingGoal: !v.editingGoal, popup: null, popupScroll: 0 }))
    case 'goal': {
      const s = await edit($, (cur, now) => setGoal(cur, a.text, 'person', now))
      await setView($, v => ({ ...v, editingGoal: false, popup: null, popupScroll: 0 }))
      if (s.detour) $.ui.toast('Return from the detour (or make it the goal) before changing the goal')
      return
    }
    case 'pin':
      await edit($, (s, now) => setNextStep(s, a.text, now))
      await setView($, v => ({ ...v, popup: null, popupScroll: 0 }))
      return
    case 'confirm': {
      const before = await snap($)
      const kind = before?.suggestions.find(x => x.id === a.id)?.kind
      await edit($, (s, now) => confirmSuggestion(s, a.id, now))
      await setView($, v => ({ ...v, popup: null, popupScroll: 0 }))
      if (kind === 'return') $.ui.toast('Return packet goes to Claude with your next message')
      if (kind === 'detour') $.ui.toast('Detour started; the atlas remembers where to come back to')
      return
    }
    case 'dismiss':
      await edit($, (s, now) => dismissSuggestion(s, a.id, now))
      await setView($, v => ({ ...v, popup: null, popupScroll: 0 }))
      return
    case 'weight':
      await edit($, s => toggleDecisionWeight(s, a.id))
      await setView($, v => ({ ...v, popup: null, popupScroll: 0 }))
      return
    case 'settle':
      await edit($, (s, now) => setItemStatus(s, a.id, 'settled', now))
      await setView($, v => ({ ...v, popup: null, popupScroll: 0 }))
      return
    case 'drop':
      await edit($, (s, now) => setItemStatus(s, a.id, 'drop', now))
      await setView($, v => ({ ...v, popup: null, popupScroll: 0 }))
      return
    case 'restore':
      await edit($, (s, now) => setItemStatus(s, a.id, 'observed', now))
      await setView($, v => ({ ...v, popup: null, popupScroll: 0 }))
      return
    case 'resolve':
      await edit($, (s, now) => setItemStatus(s, a.id, 'resolved', now))
      await setView($, v => ({ ...v, popup: null, popupScroll: 0 }))
      return
    case 'reopen':
      await edit($, (s, now) => setItemStatus(s, a.id, 'open', now))
      await setView($, v => ({ ...v, popup: null, popupScroll: 0 }))
      return
    case 'return': {
      await edit($, (s, now) => returnFromDetour(s, now))
      await setView($, v => ({ ...v, popup: null, popupScroll: 0 }))
      $.ui.toast('Return packet goes to Claude with your next message')
      return
    }
    case 'promote':
      await edit($, (s, now) => promoteDetour(s, now))
      await setView($, v => ({ ...v, popup: null, popupScroll: 0 }))
      return
    case 'mark':
      await edit($, (s, now) => mark(s, '', now))
      await setView($, v => ({ ...v, popup: null, popupScroll: 0 }))
      $.ui.toast('Checkpoint marked')
      return
  }
}

const HELP = [
  'Atlas commands (the pane buttons do the same):',
  '  /atlas                          open the pane',
  '  /atlas goal <text>              set your goal (alias: aim)',
  '  /atlas next <step>              pin the next step',
  '  /atlas mark [name]              mark a checkpoint to come back to',
  '  /atlas decision <text> [--reason <why>]   record a settled decision',
  '  /atlas detour <reason>          start a side trip from the latest mark',
  '  /atlas outcome <finding>        keep a finding from the detour',
  '  /atlas exclude <material>       set detour material aside',
  '  /atlas return                   end the detour; Claude gets one recap',
  '  /atlas promote                  make the detour your goal',
  '  /atlas observer [claude|engine] show or change the observer mode',
  '  /atlas hide <b|h>               hide report-backs (b) or hand-offs (h)',
  '  /atlas show <b|h>               show a hidden type',
  '  /atlas filters                  list hidden types',
  '  Trail: use ≡ for Trail settings: view, order and hidden types',
  '  /atlas setup                    show the first-run setup screen again',
  '  /atlas scan                     map the conversation so far with Claude (one cached request)',
  '  /atlas recover [n]              list earlier sessions, or resume number n',
  '  /atlas recover <n> full [confirm] replace this map with an Atlas save',
  "  /atlas reset                    clear this session's map",
].join('\n')

async function command($: EngineInterface, args: string): Promise<string> {
  const [verb = '', ...rest] = args.trim().split(/\s+/)
  const text = rest.join(' ')
  const s = await snap($)
  switch (verb) {
    case '':
      return (await openPane($, true)) ? 'Atlas opened.' : 'Atlas is waiting for room: widen the terminal or use /tui fullscreen.'
    case 'help':
      return HELP
    case 'filters': {
      const state = (await $.state.get(VIEW)).value as AtlasViewState | undefined
      const hidden = state?.hidden ?? []
      return hidden.length ? `Hidden types: ${hidden.map(type => `${type} (${type === 'b' ? 'report-backs' : 'hand-offs'})`).join(', ')}` : 'no filters'
    }
    case 'hide':
    case 'show': {
      const type = text.toLowerCase()
      if (type !== 'b' && type !== 'h') return 'Valid type letters: b (report-backs), h (hand-offs).'
      const state = (await $.state.get(VIEW)).value as AtlasViewState | undefined
      const current = state?.hidden ?? []
      const hidden = verb === 'hide'
        ? [...new Set([...current, type])]
        : current.filter(value => value !== type)
      await $.store.set(TRAIL_VIEW_STORE, { view: state?.trailView ?? 'story', hidden, at: await $.clock.now() })
      await setView($, value => ({ ...value, hidden }))
      const name = type === 'b' ? 'report-backs' : 'hand-offs'
      return verb === 'hide' ? `Hidden ${type} (${name}).` : `Shown ${type} (${name}).`
    }
    case 'observer': {
      const current = await modeOf($)
      if (!text) {
        const saved = await setupChoice($)
        return `Observer: ${current === 'claude' ? 'Claude' : 'Engine only'}${saved ? '' : ` (setup not chosen; /atlas setup, default: ${configuredMode === 'claude' ? 'Claude' : 'Engine only'})`}`
      }
      const requested = text.toLowerCase()
      const mode = requested === 'claude' ? 'claude' : requested === 'engine' || requested === 'engine only' ? 'engine' : null
      if (!mode) return 'Usage: /atlas observer [claude|engine]'
      await chooseObserver($, mode)
      return `Observer set to ${mode === 'claude' ? 'Claude' : 'Engine only'}.`
    }
    case 'setup':
      await setView($, v => ({ ...v, setup: true, legend: false, popup: null, popupScroll: 0, scroll: 0 }))
      await openPane($, true)
      return 'Atlas setup opened.'
    case 'goal':
    case 'aim':
      if (!text) return HELP
      if (s?.detour) return 'Return from the detour (or /atlas promote) before changing the goal.'
      await edit($, (cur, now) => setGoal(cur, text, 'person', now))
      return `Goal confirmed: ${clip(text, 140)}`
    case 'next':
      if (!text) return HELP
      await edit($, (cur, now) => setNextStep(cur, text, now))
      return `Next step pinned: ${clip(text, 140)}`
    case 'decision': {
      const [what = '', why] = text.split(/\s--reason\s/)
      if (!what.trim()) return HELP
      await edit($, (cur, now) => recordDecision(cur, what.trim(), why?.trim() || null, now))
      return `Decision settled: ${clip(what, 140)}`
    }
    case 'detour':
      if (!text) return HELP
      if (s?.detour) return `Already on a detour: ${s.detour.reason}. /atlas return first.`
      await edit($, (cur, now) => startDetour(cur, text, null, now))
      return `Detour started: ${clip(text, 120)}`
    case 'outcome':
    case 'exclude':
      if (!s?.detour) return 'No active detour.'
      if (!text) return HELP
      await edit($, (cur, now) => addDetourFinding(cur, verb === 'outcome' ? 'outcomes' : 'exclusions', text, now))
      return `${verb === 'outcome' ? 'Outcome kept' : 'Excluded'}: ${clip(text, 140)}`
    case 'return':
      if (!s?.detour) return 'No active detour.'
      await edit($, (cur, now) => returnFromDetour(cur, now))
      return `Returned from: ${s.detour.reason}. The return packet goes to Claude with your next message.`
    case 'promote':
      if (!s?.detour) return 'No active detour.'
      await edit($, (cur, now) => promoteDetour(cur, now))
      return `Goal is now: ${s.detour.reason}`
    case 'mark':
      await edit($, (cur, now) => mark(cur, text, now))
      return 'Checkpoint marked.'
    case 'recover': {
      await loadRecall($)
      const list = (await snap($))?.recall ?? []
      if (!list.length) return 'No earlier sessions found in this project.'
      const [numberText = '', mode = '', confirmation = ''] = rest
      const n = Number(numberText)
      if (text && Number.isInteger(n) && n >= 1 && n <= list.length) {
        const pick = list[n - 1]
        if (!pick) return 'No such session.'
        if (mode.toLowerCase() === 'full') {
          if (pick.source !== 'atlas') return 'Full recovery is available only for Atlas save files.'
          const current = await snap($)
          if (current && hasReplaceableContent(current) && confirmation.toLowerCase() !== 'confirm') {
            return 'this replaces your current map; run /atlas recover <n> full confirm to proceed'
          }
          const loaded = await readFullRecall($, pick)
          const source = loaded.source
          if (!source) return `Can't load that save: ${loaded.error ?? 'invalid Atlas save'}`
          await edit($, (cur, now) => recoverFull(cur, source, now))
          return `Loaded full map from session ${pick.sessionId.slice(0, 8)}`
        }
        await edit($, (cur, now) => adoptRecall(cur, pick.id, now))
        return `Resumed ${pick.source} session ${pick.sessionId.slice(0, 8)}: ${pick.goal ?? 'no goal recorded'}`
      }
      return [
        'Earlier sessions (resume with /atlas recover <n>, or in the Evidence tab):',
        ...list.map((r, i) => `  ${i + 1}. ${r.goal ?? 'no goal'} · ${r.source} · ${r.sessionId.slice(0, 8)}${r.detour ? ` · on detour: ${r.detour}` : ''}${r.nextStep ? ` · next: ${r.nextStep}` : ''}`),
      ].join('\n')
    }
    case 'scan': {
      const rows = await history($)
      if (s?.scanned === 'none' && rows.length) await edit($, (cur, now) => ({ ...replay(cur, rows, now), scanned: 'engine' }))
      return mapWithClaude($)
    }
    case 'reset': {
      const now = await $.clock.now()
      await $.state.set(SNAP, emptySnapshot(sid, root, now))
      return 'Atlas cleared for this session.'
    }
    default:
      return `Unknown: ${verb}\n${HELP}`
  }
}

// Registration runs once per load, on whichever event reaches the module first. A hot
// reload does not always raise session.start, so every hook below also calls this.
let ready: Promise<void> | null = null
let lastProblem: string | null = null
let saving: Timer | null = null
let scanResultTimer: Timer | null = null

const EMPTY_SCAN: AtlasScanState = { active: false, startedAt: 0, result: null, resultAt: 0 }

function setup($: EngineInterface): Promise<void> {
  ready ??= (async () => {
    const failed: string[] = []
    const step = async (name: string, run: () => Promise<unknown>) => {
      try {
        await run()
      } catch (err) {
        failed.push(name)
        $.ui.log(`${PLUGIN}: ${name} failed: ${err instanceof Error ? err.message : String(err)}`)
      }
    }
    await step('command /atlas', () => $.command.register({
      name: 'atlas',
      description: 'ConversationAtlas: open the pane or set goal, next, mark, decision, detour, hide, show, filters, scan, recover, help',
      argumentHint: '[goal|next|mark|decision|detour|hide|show|filters|scan|recover|help] [text]',
    }))
    await step('session binding', () => bind($))
    // The tool is inert until setup consent. Registration itself does not call Claude;
    // this lets tests and an already-equipped model receive the short "off" result.
    await step('observe tool', () => registerObserverTool($))
    saving?.cancel()
    saving = $.clock.every(SAVE_MS, () => {
      void checkHandoffReports($).catch(() => undefined)
      void save($).catch(() => undefined)
    })
    await step('pane', () => openPane($, false))
    const problem = failed.join(', ')
    if (problem !== lastProblem) $.ui.toast(problem ? `Atlas loaded with problems: ${problem}` : 'Atlas ready: /atlas or the footer button')
    lastProblem = problem
    // A step that failed (say, before the session bound) is tried again on the next event.
    if (failed.length) ready = null
  })()
  return ready
}

// ------------------------------------------------------------------ hooks

export const register: Register = (on, options) => {
  configuredMode = options?.observer === 'engine only' ? 'engine' : 'claude'
  observerToolRegistered = false
  scanOnLaunch = options?.scanOnLaunch === 'off' || options?.scanOnLaunch === 'claude' ? options.scanOnLaunch : 'engine'
  ready = null

  on('session.start', async ($, e, next) => {
    const result = await next(e)
    await setup($)
    return result
  })

  on('session.end', async ($, e, next) => {
    scanResultTimer?.cancel()
    scanResultTimer = null
    await save($).catch(() => undefined)
    if (e.reason === 'clear') sid = ''
    return next(e)
  })

  on('prompt.compose', async ($, e, next) => {
    const result = await next(e)
    if ((await modeOf($)) !== 'claude') return result
    return { sections: [...result.sections, { id: `${PLUGIN}:rules`, text: RULES, scope: 'session' as const }] }
  })

  // What the person asked for this turn, and what the atlas hands Claude beside it.
  on('prompt.submit', async ($, e, next) => {
    if (e.origin.kind !== 'composer' && e.origin.kind !== 'bridge') return next(e)
    await ensureBound($)
    const extra: string[] = []
    let taken: string[] = []
    await update($, SNAP, cur => {
      if (!cur) return emptySnapshot(sid, root, 0)
      const [ctx, rest] = takeContext(upgrade(cur))
      taken = ctx
      return rest
    })
    extra.push(...taken)
    const view = (await $.state.get(VIEW)).value
    // Only chips still in the text count: a deleted chip sends nothing.
    const refs = view?.refs ?? {}
    const seen = new Set<string>()
    for (const m of e.text.matchAll(/\[Atlas #(\d+)[^\]]*\]/g)) {
      const n = m[1] ?? ''
      const ref = refs[n]
      if (!ref || seen.has(n)) continue
      seen.add(n)
      extra.push(`Atlas reference #${n} (${ref.kind}), attached deliberately by the user: ${ref.text}`)
    }
    const s = await snap($)
    const line = (await modeOf($)) === 'claude' && s ? intentLine(s) : null
    if (line) extra.push(line)
    return next(extra.length ? { ...e, context: [...(e.context ?? []), ...extra] } : e)
  })

  on('turn.start', async ($, e, next) => {
    const result = await next(e)
    observedThisTurn = false
    await ensureBound($)
    await checkHandoffReports($)
    const rawText = String(e.text ?? '')
    const marker = reportMarker(rawText)
    await edit($, (s, now) => {
      let nextState = startTurn(s, rawText, now)
      if (marker) {
        return reportHandoff(nextState, marker.summary, now, marker.taskId ? marker.agent ?? undefined : undefined, marker.taskId ?? undefined)
      }
      // Only a genuinely typed remainder closes an unreported hand-off. A
      // marker-only engine turn therefore neither creates a prompt nor closes
      // the running delegation.
      if (nextState.events.at(-1)?.kind === 'prompt') nextState = closeUnverifiedHandoffs(nextState, now)
      return nextState
    })
    return result
  })

  // A main turn that ends on a question Claude did not report leaves that question open.
  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId || e.reason !== 'answer' || observedThisTurn) return result
    const last = (e.answer.trim().split(/\n\s*\n/).pop() ?? '').trim()
    if (last.endsWith('?')) {
      const q = sentences(last).filter(x => x.endsWith('?')).pop()
      if (q) await edit($, (s, now) => addQuestion(s, q, 'engine', now))
    }
    return result
  })

  on('agent.spawn', async ($, e, next) => {
    const started = await next(e)
    if ('agentId' in started && started.agentId) agentNames.set(started.agentId, clip(e.description || e.subagentType, 24))
    return started
  })

  on('tool.call', { tool: TOOL }, async ($, e) => {
    if ((await modeOf($)) !== 'claude') return { result: 'Conversation Atlas observer is off; use /atlas observer claude to turn it on.' }
    const raw = e as unknown as Raw
    const list = (v: unknown) => (Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string').map(x => clip(x, 160)).filter(Boolean).slice(0, 6) : undefined)
    const shift = typeof raw.shift === 'string' && ['same', 'subtopic', 'sibling', 'possible-detour', 'return'].includes(raw.shift) ? (raw.shift as ObserveReport['shift']) : undefined
    const report: ObserveReport = {
      topic: clip(raw.topic, 60) || undefined,
      shift,
      why: clip(raw.why, 140) || undefined,
      decisions: list(raw.decisions),
      questions: list(raw.questions),
      resolved: list(raw.resolved),
      next: clip(raw.next, 140) || undefined,
      checkpoint: clip(raw.checkpoint, 60) || undefined,
      goal: clip(raw.goal, 140) || undefined,
    }
    await ensureBound($)
    await edit($, (s, now) => observe(s, report, now))
    observedThisTurn = true
    return { result: 'noted' }
  })

  // Every other tool call: an activity row while it runs, then files, tests, commits.
  on('tool.call', async ($, e, next) => {
    const tool = String(e.tool)
    const input = e as unknown as Raw
    const c = classify(tool, input)
    if (!c) return next(e)
    const delegation = handoffStart(tool, input)
    await ensureBound($)
    const aid = `a${++activitySeq}`
    const agent = e.agentId ? (agentNames.get(e.agentId) ?? 'agent') : null
    const asked = tool === 'AskUserQuestion' ? askedQuestions(input) : []
    let handoffId: string | undefined
    const reportPath = delegation ? expectedReportPath(root, delegation.brief) : null
    const existingReportFingerprint = reportPath
      ? await (async () => {
          try {
            return reportFingerprint(await $.fs.read(reportPath))
          } catch {
            return null
          }
        })()
      : null
    await edit($, (s, now) => {
      let out = startActivity(s, { id: aid, kind: c.kind, label: c.label, at: now, agent })
      if (delegation) {
        out = startHandoff(out, delegation.label, delegation.agent, delegation.brief, reportPath, now, existingReportFingerprint)
        handoffId = out.handoffs.at(-1)?.id
      }
      for (const q of asked) out = addQuestion(out, q, 'claude', now)
      return out
    })
    let ran: Awaited<ReturnType<typeof next>>
    try {
      ran = await next(e)
    } catch (err) {
      await edit($, (s, now) => endActivity(s, aid, 'failed', now))
      throw err
    }
    const failed = ran.deny !== undefined || ran.isError === true
    const result = (ran.result && typeof ran.result === 'object' ? ran.result : {}) as Raw
    const taskId = taskIdOf(ran) ?? taskIdOf(result)
    const commit = (result.gitOperation as { commit?: { sha?: string } } | undefined)?.commit
    await edit($, (s, now) => {
      let out = endActivity(s, aid, failed ? 'failed' : 'done', now, c.isTest ? `Tests ${failed ? 'failed' : 'passed'}: ${c.label.replace(/^Tests: /, '')}` : undefined)
      if (failed) return out
      for (const f of c.files) out = touchFile(out, f.path, f.op, now)
      if (c.isTest) out = addCheckpoint(out, 'Tests passed', 'tests', c.label.replace(/^Tests: /, ''), now)
      if (commit?.sha) out = addCheckpoint(out, `Commit ${commit.sha.slice(0, 7)}`, 'commit', typeof input.command === 'string' ? clip(input.command, 120) : null, now)
      if (asked.length) out = resolveQuestions(out, asked, now)
      if (tool === 'ExitPlanMode') {
        const plan = typeof result.plan === 'string' ? result.plan : typeof input.plan === 'string' ? input.plan : ''
        out = addDecision(out, planTitle(plan), 'engine', now)
      }
      return out
    })
    if (delegation && !delegation.external) {
      const summaryText = `${delegation.agent} ${failed ? 'failed' : 'completed'}`
      await edit($, (s, now) => reportHandoff(s, summaryText, now, delegation.agent, handoffId))
    }
    if (delegation && handoffId && taskId) await edit($, s => setHandoffTaskId(s, handoffId as string, taskId))
    return ran
  })

  on('command.run', { command: 'atlas' }, async ($, e) => {
    await ensureBound($)
    return { text: await command($, e.args ?? '') }
  })

  // Always in the footer while the mod is loaded: opens the pane anywhere, at any width.
  on('ui.render', { component: 'SessionMode' }, async ($, e, next) => {
    const below = await next(e)
    const s = await snap($)
    const { Box, Button } = $.ui.resolve(e)
    const waiting = s ? s.suggestions.length + openQuestions(s).length : 0
    const topic = s ? oneLine(s).replace(/^[^\p{L}\p{N}]+/u, '') : ''
    const label = s && topic && topic !== 'Atlas' ? clip(`Atlas: ${topic}${waiting ? ` · ${waiting} to review` : ''}`, 40) : waiting ? clip(`Atlas · ${waiting} to review`, 40) : 'Atlas'
    const press = async () => {
      await openPane($, true)
      if (waiting > 0) await setView($, v => ({ ...v, tab: 'open', scroll: 0 }))
    }
    return (
      <Box flexDirection="row" alignItems="center" gap={1}>
        <Button key="atlas-open" dimColor={waiting === 0} label={label} onPress={() => void press().catch(() => undefined)} />
        {below}
      </Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const t = $.ui.resolve(e)
    const { Box, Text } = t
    const s = await snap($)
    if (!s) return <Text dimColor>Atlas is starting…</Text>
    const view = { ...DEFAULT_VIEW, ...((await $.state.get(VIEW)).value ?? {}) }
    const choice = await setupChoice($)
    const renderView = { ...view, setup: view.setup || !choice }
    const mode = await modeOf($)
    const now = await $.clock.now()
    const scan = await scanState($)
    const width = Math.max(20, (e.props.bodyColumns || 48) - 2)
    const Client = 'Client' in t ? t.Client : undefined
    const live = (key: string, rows: LiveRow[], scanProps?: { active: boolean; startedAt: number; result: string | null; resultAt: number; now: number }) =>
      Client ? (
        <Client key={`live-${key}`} module="./live.tsx" props={scanProps ? { rows: plain(rows), tones: TONES, scan: scanProps } : { rows: plain(rows), tones: TONES }} />
      ) : (
        <Box key={`live-${key}`} flexDirection="column">
          {rows.map((r, i) => (
            <Text key={`static-${i}`} wrap="truncate-end">{r.segs.map(seg => (seg.spin ? '… ' : seg.t)).join('')}</Text>
          ))}
        </Box>
      )
    const el = { Box: t.Box, Text: t.Text, Button: t.Button, Input: 'Input' in t ? t.Input : undefined, Select: 'Select' in t ? t.Select : undefined, Svg: 'Svg' in t ? t.Svg : undefined, Link: 'Link' in t ? t.Link : undefined, Code: 'Code' in t ? t.Code : undefined, Markdown: 'Markdown' in t ? t.Markdown : undefined }
    const rows = Math.max(8, e.props.scroll?.bodyRows ?? e.viewport?.rows ?? 30)
    const surface = (e.surface ?? 'terminal') as Surface
    const drawn = pane({
      el, surface, width, rows, now, mode, setupDefault: configuredMode, scan, view: renderView, live,
      act: a => void act($, a, surface).catch(err => $.ui.toast(`atlas: ${err instanceof Error ? err.message : String(err)}`)),
    }, s)
    drawnSurfaces.add(surface)
    surfaceBounds.set(surface, {
      bodyRows: rows,
      maxScroll: drawn.maxScroll,
      maxPopupScroll: drawn.maxPopupScroll,
      maxExpandedScroll: drawn.maxExpandedScroll,
      maxLegendScroll: drawn.maxLegendScroll,
    })
    return drawn.tree
  })

  // The terminal pane scrolls its own body (the app bar stays pinned), unless a popup or
  // expanded help or a Trail event is using the same wheel gesture.
  on('ui.scroll', { component: 'Pane', requestId: PANE }, async ($, e, next) => {
    // Desktop moves before this hook fires (#99449); blocking would snap it back.
    // With both surfaces drawn, keep the old branches; desktop wheel is swallowed for 0.1.
    // Only a non-terminal (GUI) surface has drawn: the host scrolls its full-length tree itself. The seam keeps the GUI's name out of this file.
    if (drawnSurfaces.size > 0 && !drawnSurfaces.has('terminal')) return next(e)
    const { maxScroll, maxPopupScroll, maxExpandedScroll, maxLegendScroll } = wheelBounds(e.bodyRows)
    const view = (await $.state.get(VIEW)).value as AtlasView | undefined
    if (view?.popup) {
      if (view.popup.kind === 'trail-view') {
        await setView($, v => ({ ...v, settingsPage: Math.max(0, Math.min(2, v.settingsPage + Math.sign(e.by))) }))
        return {}
      }
      await setView($, v => ({ ...v, popupScroll: Math.max(0, Math.min(maxPopupScroll, v.popupScroll + e.by)) }))
      return {}
    }
    if (view?.legend) {
      await setView($, v => ({ ...v, legendScroll: Math.max(0, Math.min(maxLegendScroll, v.legendScroll + e.by)) }))
      return {}
    }
    if (view?.expanded && maxExpandedScroll > 0) {
      await setView($, v => ({ ...v, expandedScroll: Math.max(0, Math.min(maxExpandedScroll, v.expandedScroll + e.by)) }))
      return {}
    }
    await setView($, v => ({ ...v, scroll: Math.max(0, Math.min(maxScroll, v.scroll + e.by)) }))
    return {}
  })
}

files.hooks/activity.ts:
// Turns a tool call into an activity row and the files it touched. Pure; no `$`.

import type { AtlasActivityKind } from '../types'

export type Classified = {
  kind: AtlasActivityKind
  label: string
  files: { path: string; op: 'read' | 'write' }[]
  isTest: boolean
}

type Input = Record<string, unknown>

const str = (v: unknown): string => (typeof v === 'string' ? v : '')

export function posix(path: string): string {
  return path.replace(/\\/g, '/')
}

export function base(path: string): string {
  const p = posix(path).replace(/\/+$/, '')
  return p.slice(p.lastIndexOf('/') + 1) || p
}

// Path shown relative to the project root when inside it.
export function rel(path: string, root: string): string {
  const p = posix(path)
  const r = posix(root).replace(/\/+$/, '')
  if (r && p.toLowerCase().startsWith(`${r.toLowerCase()}/`)) return p.slice(r.length + 1)
  return p
}

const TEST_CMD = /(^|[\s;&|(])((npm|pnpm|yarn|bun)( run)? test|npx (vitest|jest|mocha|playwright)|vitest|jest|pytest|py\.test|cargo test|go test|dotnet test|mvn test|gradle test|node --test|deno test|claude plugin test|rspec|phpunit|ctest|make (test|check))\b/
const GIT_CMD = /(^|[\s;&|(])(git|gh)\s+(\w+)/

export function isTestCommand(command: string): boolean {
  return TEST_CMD.test(command)
}

function shortCommand(command: string): string {
  const first = command.split('\n')[0] ?? command
  return first.replace(/^cd\s+\S+\s*&&\s*/, '').trim()
}

export function classify(tool: string, input: Input): Classified | null {
  const none: Classified['files'] = []
  switch (tool) {
    case 'Read': {
      const path = posix(str(input.file_path))
      return { kind: 'read', label: `Read ${base(path)}`, files: path ? [{ path, op: 'read' }] : none, isTest: false }
    }
    case 'Edit':
    case 'MultiEdit':
    case 'Write':
    case 'NotebookEdit': {
      const path = posix(str(input.file_path) || str(input.notebook_path))
      const verb = tool === 'Write' ? 'Write' : 'Edit'
      return { kind: 'edit', label: `${verb} ${base(path)}`, files: path ? [{ path, op: 'write' }] : none, isTest: false }
    }
    case 'Grep':
      return { kind: 'search', label: `Search "${str(input.pattern).slice(0, 40)}"`, files: none, isTest: false }
    case 'Glob':
      return { kind: 'search', label: `Find ${str(input.pattern).slice(0, 40)}`, files: none, isTest: false }
    case 'Bash':
    case 'PowerShell': {
      const command = str(input.command)
      const short = shortCommand(command)
      if (isTestCommand(command)) return { kind: 'test', label: `Tests: ${short}`, files: none, isTest: true }
      const git = GIT_CMD.exec(command)
      if (git) return { kind: 'git', label: `${git[2]} ${git[3]}${str(input.description) ? ` · ${str(input.description)}` : ''}`, files: none, isTest: false }
      return { kind: 'bash', label: str(input.description) || short, files: none, isTest: false }
    }
    case 'WebFetch':
      return { kind: 'web', label: `Fetch ${str(input.url).replace(/^https?:\/\//, '').slice(0, 50)}`, files: none, isTest: false }
    case 'WebSearch':
      return { kind: 'web', label: `Search web "${str(input.query).slice(0, 40)}"`, files: none, isTest: false }
    case 'Agent':
    case 'Task':
      return { kind: 'agent', label: `Agent: ${str(input.description) || str(input.subagent_type) || 'subagent'}`, files: none, isTest: false }
    case 'AskUserQuestion':
      return { kind: 'ask', label: 'Asking you', files: none, isTest: false }
    case 'ExitPlanMode':
      return { kind: 'plan', label: 'Plan proposed', files: none, isTest: false }
    case 'TodoWrite':
    case 'ToolSearch':
      return null
    default: {
      if (tool.startsWith('mcp__conversation-atlas__')) return null
      const mcp = /^mcp__(.+?)__(.+)$/.exec(tool)
      if (mcp) return { kind: 'other', label: `${mcp[1]?.replace(/^claude_ai_/, '')}: ${mcp[2]}`, files: none, isTest: false }
      return { kind: 'other', label: tool, files: none, isTest: false }
    }
  }
}

// The question texts of an AskUserQuestion call: each becomes an open question on the map.
export function askedQuestions(input: Input): string[] {
  const qs = Array.isArray(input.questions) ? input.questions : []
  return qs.map(q => (q && typeof q === 'object' ? str((q as Input).question) : '')).filter(Boolean)
}

// The first heading or line of a proposed plan, used as the decision's text.
export function planTitle(plan: string): string {
  const line = plan.split('\n').map(l => l.replace(/^#+\s*/, '').trim()).find(Boolean)
  return line ? `Plan approved: ${line}` : 'Plan approved'
}

files.hooks/live.tsx:
// Surface module for the parts of the atlas that move: running activity spins, and a
// segment marked with a tone shimmers (a bright band sweeping through its letters) while
// it is fresh or running. Runs on the drawing thread; the hooks module only hands it rows.

import type { ClientModule } from 'claude-code'

export type LiveSeg = { t: string; c?: string; b?: boolean; d?: boolean; sh?: string; spin?: boolean }
export type LiveRow = { segs: LiveSeg[]; right?: LiveSeg[] }
export type LiveScan = { active: boolean; startedAt: number; result: string | null; resultAt: number; now: number }
export type LiveProps = { rows: LiveRow[]; tones: Record<string, string[]>; scan?: LiveScan }

type Local = { phase: number; ref: { stop?: () => void }; scanKey: string; elapsedMs: number }

const TICK_MS = 100
const FRAMES = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏']

function band(i: number, phase: number, len: number, palette: string[]): string {
  const at = ((phase * 1.4) % (len + 10)) - 5
  const d = Math.abs(i - at)
  return palette[d < 1 ? 3 : d < 2 ? 2 : d < 3 ? 1 : 0] ?? palette[0] ?? '#bb9af7'
}

function scanBar(width: number, phase: number): string {
  const len = Math.max(8, width)
  const at = phase % len
  return Array.from({ length: len }, (_, i) => i === at ? '█' : '─').join('')
}

const Live: ClientModule<LiveProps, Local> = (props, surface) => {
  const { Box, Text } = surface.elements
  let state = surface.state
  if (state === undefined) {
    state = { phase: 0, ref: {}, scanKey: '', elapsedMs: 0 }
    surface.setState(state)
  }
  const scan = props.scan
  const scanKey = scan ? `${scan.active ? 'active' : 'result'}:${scan.startedAt}:${scan.resultAt}:${scan.result ?? ''}` : ''
  if (state.scanKey !== scanKey) {
    const elapsedMs = scan
      ? scan.active
        ? Math.max(0, scan.now - scan.startedAt)
        : Math.max(0, scan.now - scan.resultAt)
      : 0
    state = { ...state, scanKey, elapsedMs }
    surface.setState(state)
  }
  const moving = props.rows.some(r => r.segs.some(s => s.sh || s.spin)) || Boolean(scan?.active)
  if (moving && !state.ref.stop) {
    state.ref.stop = surface.every(TICK_MS, () => {
      const cur = surface.state
      if (cur) surface.setState({ ...cur, phase: cur.phase + 1, elapsedMs: cur.elapsedMs + TICK_MS })
    })
  } else if (!moving && state.ref.stop) {
    state.ref.stop()
    state.ref.stop = undefined
  }
  const phase = state.phase
  const draw = (s: LiveSeg) => {
    if (s.spin) return <Text color={s.c} bold>{`${FRAMES[phase % FRAMES.length]} `}</Text>
    const palette = s.sh ? props.tones[s.sh] : undefined
    if (!palette) {
      return (
        <Text color={s.c} bold={s.b} dimColor={s.d}>
          {s.t}
        </Text>
      )
    }
    const chars = [...s.t]
    return (
      <Text bold={s.b}>
        {chars.map((ch, i) => (
          <Text color={band(i, phase, chars.length, palette)}>{ch}</Text>
        ))}
      </Text>
    )
  }
  const drawRow = (r: LiveRow) => (
    <Box flexDirection="row" height={1} overflow="hidden">
      <Box flexDirection="row" flexShrink={1} overflow="hidden">
        {r.segs.map(draw)}
      </Box>
      <Box flexGrow={1} />
      {r.right?.length ? (
        <Box flexDirection="row" flexShrink={0}>
          {r.right.map(draw)}
        </Box>
      ) : null}
    </Box>
  )
  if (scan?.active) {
    return (
      <Box flexDirection="column">
        <Text color="#7aa2f7">{scanBar(surface.columns, phase)}</Text>
        <Box flexDirection="row" height={1} overflow="hidden">
          <Box flexDirection="row" flexShrink={1} overflow="hidden">{props.rows[0]?.segs.map(draw)}</Box>
          <Box flexGrow={1} />
          <Text dimColor>{`${Math.floor(state.elapsedMs / 1000)}s`}</Text>
        </Box>
      </Box>
    )
  }
  return (
    <Box flexDirection="column">
      {props.rows.map(drawRow)}
    </Box>
  )
}

export default Live

files.hooks/delegation.ts:
// Pure delegation detection and handoff-report parsing. The register hook owns
// the filesystem and state writes; this module only interprets tool inputs and
// report text.

export type HandoffStart = {
  label: string
  agent: string
  brief: string | null
  external: boolean
}

export type HandoffReport = {
  status: 'done' | 'blocked' | 'failed'
  summary: string
  branch: string
  tests: string
  files: string[]
}

type Input = Record<string, unknown>

const stringOf = (value: unknown): string => typeof value === 'string' ? value : ''

function labelOf(value: string): string {
  const line = value.replace(/\s+/g, ' ').trim()
  return line.length <= 120 ? line : `${line.slice(0, 119).trimEnd()}…`
}

function titleOf(command: string): string | null {
  const match = /(?:^|\s)--title(?:=|\s+)(?:"([^"]+)"|'([^']+)'|(\S+))/i.exec(command)
  return match?.[1] ?? match?.[2] ?? match?.[3] ?? null
}

function agentOf(command: string): string | null {
  const direct = /(?:^|&&|[;|])\s*(?:[A-Za-z_][\w-]*=\S+\s+)*(?:["']?)(codex|claude)(?:\.exe)?(?=\s|$)/gi
  for (const match of command.matchAll(direct)) {
    const name = match[1]?.toLowerCase()
    if (name === 'codex') return 'Codex'
    if (name === 'claude') {
      const rest = command.slice((match.index ?? 0) + match[0].length)
      if (/^\s+(?:-p|--print)(?:\s|$)/i.test(rest)) return 'Claude'
    }
  }
  const terminal = /\bwt(?:\.exe)?\b[\s\S]*?\bnew-tab\b([\s\S]*)/i.exec(command)?.[1] ?? ''
  if (/(?:^|\s)(?:["']?)(codex|claude)(?:\.exe)?(?=\s|$)/i.test(terminal)) {
    const match = /(?:^|\s)(?:["']?)(codex|claude)(?:\.exe)?(?=\s|$)/i.exec(terminal)
    if (match?.[1]?.toLowerCase() === 'codex') return 'Codex'
    if (match?.[1] && /\s+(?:-p|--print)(?:\s|$)/i.test(terminal.slice((match.index ?? 0) + match[0].length))) return 'Claude'
  }
  return null
}

function briefOf(command: string): string | null {
  const matches = [...command.matchAll(/(?:^|[\s"'])([A-Za-z]:[\\/][^\s"']+\.md|(?:\.\.?[\\/])?[^\s"']+\.md)\b/gi)]
  return matches.at(-1)?.[1] ?? null
}

export function handoffStart(tool: string, input: Input): HandoffStart | null {
  if (tool === 'Agent' || tool === 'Task') {
    const agent = stringOf(input.subagent_type) || stringOf(input.subagentType) || 'subagent'
    const label = labelOf(stringOf(input.description)) || agent
    return { label, agent, brief: null, external: false }
  }
  if (tool !== 'Bash' && tool !== 'PowerShell') return null
  const command = stringOf(input.command)
  const agent = agentOf(command)
  const terminalTab = /\bwt(?:\.exe)?\b[\s\S]*\bnew-tab\b/i.test(command) && Boolean(agent)
  const external = Boolean(agent || terminalTab)
  if (!external) return null
  const description = labelOf(stringOf(input.description))
  const firstCommandLine = labelOf(command.split(/\r?\n/, 1)[0] ?? '')
  const name = agent ? (titleOf(command) || agent) : (description || firstCommandLine || 'background')
  return { label: name, agent: agent ?? 'background', brief: briefOf(command), external: true }
}

export function expectedReportPath(root: string, brief: string | null): string | null {
  if (!brief) return null
  const name = brief.replace(/\\/g, '/').split('/').at(-1) ?? ''
  const slug = name.replace(/\.md$/i, '')
  if (!slug || !/^[A-Za-z0-9._-]+$/.test(slug)) return null
  return `${root.replace(/[\\/]$/, '').replace(/\\/g, '/')}/.claude/atlas/handoffs/${slug}.md`
}

function cleanValue(value: string): string {
  return value.replace(/^['"]|['"]$/g, '').trim()
}

// A short, deterministic fingerprint is enough to distinguish a report left by
// an earlier hand-off from the report written by the current one.
export function reportFingerprint(text: unknown): string | null {
  if (typeof text !== 'string') return null
  let hash = 2166136261
  for (let i = 0; i < text.length; i++) hash = Math.imul(hash ^ text.charCodeAt(i), 16777619)
  return `${text.length}:${hash >>> 0}`
}

export function reportChanged(previous: string | null | undefined, current: unknown): boolean {
  const next = reportFingerprint(current)
  return next !== null && next !== previous
}

// A missing optional field is not a malformed report. A missing/invalid status
// is the one condition that keeps a report open, so a partially written file
// can safely be observed on the next timer tick.
export function parseHandoffReport(text: unknown): HandoffReport | null {
  if (typeof text !== 'string' || !text.trim()) return null
  const lines = text.replace(/^---\s*\r?\n/, '').split(/\r?\n/)
  let status: HandoffReport['status'] | null = null
  let summary = ''
  let branch = ''
  let tests = ''
  const files: string[] = []
  let inFiles = false
  for (const raw of lines) {
    const line = raw.trim()
    if (!line) {
      inFiles = false
      continue
    }
    if (line === '---') continue
    if (/^files\s*:/i.test(line)) {
      inFiles = true
      const inline = line.replace(/^files\s*:\s*/i, '').trim()
      if (inline && inline !== '[]') files.push(cleanValue(inline.replace(/^[-*]\s*/, '')))
      continue
    }
    const field = /^(status|summary|branch|tests)\s*:\s*(.*)$/i.exec(line)
    if (field) {
      inFiles = false
      const value = cleanValue(field[2] ?? '')
      if (field[1]?.toLowerCase() === 'status' && (value === 'done' || value === 'blocked' || value === 'failed')) status = value
      if (field[1]?.toLowerCase() === 'summary') summary = value
      if (field[1]?.toLowerCase() === 'branch') branch = value
      if (field[1]?.toLowerCase() === 'tests') tests = value
      continue
    }
    if (inFiles && /^[A-Za-z][A-Za-z0-9_.-]*\s*:\s*/.test(line)) {
      inFiles = false
      continue
    }
    if (inFiles) files.push(cleanValue(line.replace(/^[-*]\s+/, '')))
  }
  if (!status) return null
  return {
    status,
    summary: summary || 'No summary provided',
    branch: branch || 'unknown',
    tests: tests || 'tests not recorded',
    files: [...new Set(files.filter(Boolean))],
  }
}

files.hooks/model.ts:
// Pure reducers for Conversation Atlas. No `$`, no clock: every function takes the
// snapshot and the time, and returns a new snapshot. The hooks module wires them to events.
//
// The one rule this file enforces: observations never write intent. `observe`, `startTurn`
// and the activity reducers only add topics, suggestions, items, files and activity.
// Goal, detour, next step and marked checkpoints change only in the `confirm*`/`set*`
// functions, which the hooks call from a person's press or command.

import type {
  AtlasActivity,
  AtlasCheckpoint,
  AtlasDetour,
  AtlasEvent,
  AtlasFile,
  AtlasHandoff,
  AtlasItem,
  AtlasRecall,
  AtlasSnapshot as BaseSnapshot,
  AtlasSource,
  AtlasSuggestion,
  AtlasSuggestionKind,
  AtlasTopic,
} from '../types'

// Optional at the type boundary because pre-focus snapshots are still supported.
// All constructors/loaders below provide a plain JSON field with a null default.
export type AtlasFocus = { text: string; since: number; turns: number; lastTurn: number }
export type AtlasSnapshot = BaseSnapshot & { focus?: AtlasFocus | null }

export const LIMITS = {
  events: 200,
  activity: 24,
  files: 60,
  topics: 80,
  items: 60,
  checkpoints: 40,
  suggestions: 10,
  history: 20,
  handoffs: 20,
  focusText: 140,
  focusTurns: 2,
} as const

export type Shift = 'same' | 'subtopic' | 'sibling' | 'possible-detour' | 'return'

export type ObserveReport = {
  topic?: string
  shift?: Shift
  why?: string
  decisions?: string[]
  questions?: string[]
  resolved?: string[]
  next?: string
  checkpoint?: string
  goal?: string
}

export function clip(value: unknown, max = 120): string {
  if (typeof value !== 'string') return ''
  const text = value.replace(/\s+/g, ' ').trim()
  return text.length <= max ? text : `${text.slice(0, Math.max(1, max - 1)).trimEnd()}…`
}

export function norm(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim()
}

function words(value: string): Set<string> {
  return new Set(norm(value).split(' ').filter(w => w.length > 2))
}

// Loose match for "the question Claude says is resolved" and "the topic it returns to".
export function similar(a: string, b: string): boolean {
  const x = norm(a)
  const y = norm(b)
  if (!x || !y) return false
  if (x === y || x.includes(y) || y.includes(x)) return true
  const wa = words(a)
  const wb = words(b)
  if (wa.size === 0 || wb.size === 0) return false
  let shared = 0
  for (const w of wa) if (wb.has(w)) shared += 1
  return shared / Math.min(wa.size, wb.size) >= 0.6
}

export function emptySnapshot(sessionId: string, root: string, now: number): AtlasSnapshot {
  return {
    v: 1,
    sessionId,
    root,
    startedAt: now,
    turn: 0,
    seq: 0,
    goal: null,
    focus: null,
    detectedGoal: null,
    goalHistory: [],
    detour: null,
    detourHistory: [],
    nextStep: null,
    topics: [],
    currentTopicId: null,
    suggestions: [],
    decisions: [],
    questions: [],
    checkpoints: [],
    files: [],
    activity: [],
    handoffs: [],
    events: [],
    pendingContext: [],
    recall: [],
    adopted: [],
    scanned: 'none',
    fresh: [],
  }
}

// Fill fields a snapshot saved by an older build may lack, so a restore never breaks a render.
export function hydrate(raw: unknown, sessionId: string, root: string, now: number): AtlasSnapshot {
  const base = emptySnapshot(sessionId, root, now)
  if (!raw || typeof raw !== 'object') return base
  const s = raw as Partial<AtlasSnapshot>
  if (s.v !== 1) return base
  const detour = s.detour ? { ...s.detour, exclusions: s.detour.exclusions ?? [] } : null
  return {
    ...base,
    ...s,
    focus: boundedFocus(s.focus),
    detour,
    sessionId,
    root,
    fresh: [],
    activity: (s.activity ?? []).map(a => (a.state === 'running' ? { ...a, state: 'failed' as const, endedAt: a.endedAt ?? now } : a)),
    handoffs: (s.handoffs ?? []).map(h => ({
      ...h,
      reportFingerprint: h.reportFingerprint ?? null,
      taskId: h.taskId ?? null,
      ...(h.status === 'open' ? { status: 'closed' as const, summary: h.summary ?? 'session ended', tests: h.tests ?? null } : {}),
    })),
  }
}

type RawSnapshot = Record<string, unknown>

function isRawRecord(value: unknown): value is RawSnapshot {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value)
}

function focusError(value: unknown): string | null {
  if (value === undefined || value === null) return null
  if (!isRawRecord(value) || typeof value.text !== 'string' || !clip(value.text) ||
    ![value.since, value.turns, value.lastTurn].every(n => typeof n === 'number' && Number.isSafeInteger(n) && n >= 0) ||
    Number(value.turns) < 1 || Number(value.lastTurn) < Number(value.since)) return 'malformed focus record'
  return null
}

function boundedFocus(value: unknown): AtlasFocus | null {
  if (value == null || focusError(value)) return null
  const focus = value as AtlasFocus
  return { text: clip(focus.text, LIMITS.focusText), since: focus.since,
    turns: Math.min(focus.turns, LIMITS.focusTurns), lastTurn: focus.lastTurn }
}

const requiredRecordArrays = ['goalHistory', 'detourHistory', 'topics', 'suggestions', 'decisions', 'questions', 'checkpoints', 'files', 'activity', 'events']
const optionalRecordArrays = ['handoffs', 'recall']
const optionalStringArrays = ['pendingContext', 'adopted', 'fresh']

function arrayShapeError(raw: RawSnapshot, field: string, required: boolean): string | null {
  if (raw[field] === undefined && !required) return null
  if (!Array.isArray(raw[field])) return `${required ? 'missing or malformed' : 'malformed'} ${field} collection`
  return null
}

function recordArrayError(raw: RawSnapshot, field: string, required: boolean): string | null {
  const shapeError = arrayShapeError(raw, field, required)
  if (shapeError || raw[field] === undefined) return shapeError
  return (raw[field] as unknown[]).every(isRawRecord) ? null : `malformed ${field} collection`
}

function stringArrayError(raw: RawSnapshot, field: string): string | null {
  const shapeError = arrayShapeError(raw, field, false)
  if (shapeError || raw[field] === undefined) return shapeError
  return (raw[field] as unknown[]).every(value => typeof value === 'string') ? null : `malformed ${field} collection`
}

function nullableRecordError(raw: RawSnapshot, field: string): string | null {
  const value = raw[field]
  return value === undefined || value === null || isRawRecord(value) ? null : `malformed ${field} record`
}

function nestedArrayError(record: RawSnapshot, field: string, label: string): string | null {
  if (record[field] === undefined) return null
  if (!Array.isArray(record[field])) return `malformed ${label} collection`
  return (record[field] as unknown[]).every(value => typeof value === 'string') ? null : `malformed ${label} collection`
}

function detourShapeError(value: unknown, label: string): string | null {
  if (!isRawRecord(value)) return `malformed ${label} record`
  const departure = value.departure
  if (!isRawRecord(departure)) return `malformed ${label} record`
  return nestedArrayError(value, 'outcomes', `${label}.outcomes`) ??
    nestedArrayError(value, 'exclusions', `${label}.exclusions`) ??
    nestedArrayError(departure, 'decisions', `${label}.departure.decisions`)
}

// Full recovery is a replacement, so reject malformed snapshots before hydrate can
// turn an unsupported or incomplete shape into a seemingly valid empty snapshot.
export function snapshotError(raw: unknown): string | null {
  if (!isRawRecord(raw)) return 'snapshot is not an object'
  if (raw.v !== 1) return `unsupported version ${raw.v === undefined ? 'missing' : String(raw.v)}`
  const error = focusError(raw.focus)
  if (error) return error
  for (const field of requiredRecordArrays) {
    const error = recordArrayError(raw, field, true)
    if (error) return error
  }
  for (const field of optionalRecordArrays) {
    const error = recordArrayError(raw, field, false)
    if (error) return error
  }
  for (const field of optionalStringArrays) {
    const error = stringArrayError(raw, field)
    if (error) return error
  }
  for (const field of ['goal', 'detectedGoal']) {
    const error = nullableRecordError(raw, field)
    if (error) return error
  }
  for (const field of ['detour', 'detourHistory']) {
    const value = raw[field]
    if (field === 'detour') {
      if (value !== undefined && value !== null) {
        const error = detourShapeError(value, field)
        if (error) return error
      }
      continue
    }
    for (const item of value as unknown[]) {
      const error = detourShapeError(item, field)
      if (error) return error
    }
  }
  return null
}

// A snapshot that survived a reload of an older build keeps its old shape in state:
// fill every field added since, so no reader ever meets undefined. Cheap and idempotent.
export function upgrade(s: AtlasSnapshot): AtlasSnapshot {
  const partial = s as Partial<AtlasSnapshot>
  const needs =
    partial.focus === undefined ||
    partial.detectedGoal === undefined ||
    !Array.isArray(partial.recall) ||
    !Array.isArray(partial.adopted) ||
    !partial.scanned ||
    !Array.isArray(partial.handoffs) ||
    s.handoffs.some(h => h.reportFingerprint === undefined || h.taskId === undefined) ||
    (s.detour && !Array.isArray(s.detour.exclusions)) ||
    s.detourHistory.some(d => !Array.isArray(d.exclusions))
  if (!needs) return s
  const base = emptySnapshot(s.sessionId, s.root, s.startedAt)
  const withEx = <T extends { exclusions?: string[] }>(d: T) => ({ ...d, exclusions: d.exclusions ?? [] })
  return {
    ...base,
    ...s,
    focus: boundedFocus(partial.focus),
    detectedGoal: partial.detectedGoal ?? null,
    recall: partial.recall ?? [],
    adopted: partial.adopted ?? [],
    scanned: partial.scanned ?? 'none',
    handoffs: (partial.handoffs ?? []).map(h => ({ ...h, reportFingerprint: h.reportFingerprint ?? null, taskId: h.taskId ?? null })),
    detour: s.detour ? withEx(s.detour) : null,
    detourHistory: s.detourHistory.map(withEx),
  }
}

function id(s: AtlasSnapshot, prefix: string): [string, AtlasSnapshot] {
  const seq = s.seq + 1
  return [`${prefix}${seq}`, { ...s, seq }]
}

function keep<T>(list: T[], max: number): T[] {
  return list.length > max ? list.slice(list.length - max) : list
}

function event(s: AtlasSnapshot, kind: AtlasEvent['kind'], text: string, now: number, detail?: string[]): AtlasSnapshot {
  const [eid, next] = id(s, 'e')
  const made: AtlasEvent = { id: eid, at: now, turn: s.turn, kind, text: kind === 'prompt' ? text : clip(text, 160), ...(detail?.length ? { detail } : {}) }
  return { ...next, events: keep([...next.events, made], LIMITS.events) }
}

// Rendering a long run of identical evidence rows as one event keeps the Trail
// useful without growing the stored event list or changing LIMITS.
export function collapseEvents(events: AtlasEvent[]): AtlasEvent[] {
  const out: AtlasEvent[] = []
  for (const current of events) {
    const previous = out[out.length - 1]
    const currentText = current.text.replace(/ ×\d+$/, '')
    const previousText = previous?.text.replace(/ ×\d+$/, '') ?? ''
    if (previous && current.kind === 'checkpoint' && previous.kind === 'checkpoint' && currentText === previousText) {
      const count = Number(/ ×(\d+)$/.exec(previous.text)?.[1] ?? 1) + 1
      out[out.length - 1] = { ...current, text: `${currentText} ×${count}` }
    } else {
      out.push(current)
    }
  }
  return out
}

function flash(s: AtlasSnapshot, ...ids: string[]): AtlasSnapshot {
  return { ...s, fresh: [...new Set([...s.fresh, ...ids])].slice(-12) }
}

export function clearFresh(s: AtlasSnapshot): AtlasSnapshot {
  return s.fresh.length ? { ...s, fresh: [] } : s
}

export function currentTopic(s: AtlasSnapshot): AtlasTopic | null {
  return s.topics.find(t => t.id === s.currentTopicId) ?? null
}

// Count only topic observations, once per turn. A different candidate or a gap
// resets the run; similar wording in the immediately following turn reaches two.
// startTurn advances the clock but never counts the previous turn's stale topic.
// Matching the confirmed goal (or no topic) immediately restores goal focus.
// This reducer writes no intent, fresh mark or Trail event.
function observeFocus(s: AtlasSnapshot): AtlasSnapshot {
  const goal = s.goal?.text
  if (!goal) return s.focus == null ? s : { ...s, focus: null }
  const topic = currentTopic(s)?.title
  const text = clip(!topic || similar(topic, goal) ? goal : topic, LIMITS.focusText)
  const previous = s.focus
  const same = Boolean(previous && similar(previous.text, text))
  const consecutive = same && previous!.lastTurn === s.turn - 1
  const repeated = same && previous!.lastTurn === s.turn
  const turns = repeated ? previous!.turns : consecutive ? Math.min(LIMITS.focusTurns, previous!.turns + 1) : 1
  return { ...s, focus: { text, since: repeated || consecutive ? previous!.since : s.turn, turns, lastTurn: s.turn } }
}

export function focusedGoal(s: AtlasSnapshot): string | null {
  if (!s.goal) return null
  return s.focus && s.focus.turns >= LIMITS.focusTurns && !similar(s.focus.text, s.goal.text)
    ? s.focus.text : s.goal.text
}

// Derived alternatives are intentionally not stored as suggestions: they are a
// read-only view of observed evidence until the person presses Switch to this.
export function goalSuggestions(s: AtlasSnapshot): string[] {
  const goal = s.goal?.text
  if (!goal) return []
  const focus = focusedGoal(s)
  const moved = focus && !similar(focus, goal) ? focus : null
  // A detour still blocks setGoal, but must not hide the observed focus row.
  // Its existing goal Action explains that Return/promote is required first.
  if (s.detour) return moved ? [moved] : []
  const recentMain = s.topics.filter(topic => topic.kind === 'main').slice(-5)
  const current = currentTopic(s)
  const recentEvidence = [current?.title, ...recentMain.map(topic => topic.title)].filter((text): text is string => Boolean(text))
  if (!moved && (!recentEvidence.length || recentEvidence.some(text => similar(text, goal)))) return []

  const candidates = [
    moved,
    s.detectedGoal?.text,
    current?.title,
    ...recentMain
      .slice()
      .reverse()
      .map(topic => topic.title),
    ...s.checkpoints
      .filter(checkpoint => checkpoint.kind === 'claude')
      .slice(-5)
      .reverse()
      .map(checkpoint => checkpoint.name),
  ]
  const out: string[] = []
  for (const candidate of candidates) {
    const text = clip(candidate, 140)
    if (!text || similar(text, goal) || out.some(existing => similar(existing, text))) continue
    out.push(text)
    if (out.length === 3) break
  }
  return out
}

// Root-to-current chain of the topic tree: the "current path".
export function pathOf(s: AtlasSnapshot, topicId = s.currentTopicId): AtlasTopic[] {
  const chain: AtlasTopic[] = []
  const seen = new Set<string>()
  let cur = s.topics.find(t => t.id === topicId) ?? null
  while (cur && !seen.has(cur.id)) {
    seen.add(cur.id)
    chain.unshift(cur)
    cur = cur.parentId ? (s.topics.find(t => t.id === cur?.parentId) ?? null) : null
  }
  return chain
}

export function activeDecisions(s: AtlasSnapshot): AtlasItem[] {
  return s.decisions.filter(d => d.status === 'observed' || d.status === 'settled')
}

export function openQuestions(s: AtlasSnapshot): AtlasItem[] {
  return s.questions.filter(q => q.status === 'open')
}

// ---------------------------------------------------------------- suggestions

function suggest(
  s: AtlasSnapshot,
  kind: AtlasSuggestionKind,
  text: string,
  why: string | null,
  source: AtlasSource,
  now: number,
  replaceKind = true,
): AtlasSnapshot {
  const body = clip(text, 140)
  if ((body.replace(/…/g, '').match(/[\p{L}\p{N}]/gu)?.length ?? 0) < 2) return s
  if (s.suggestions.some(x => x.kind === kind && similar(x.text, body))) return s
  const [sid, next] = id(s, 's')
  const kept = replaceKind ? next.suggestions.filter(x => x.kind !== kind) : next.suggestions
  const made: AtlasSuggestion = { id: sid, kind, text: body, why: why ? clip(why, 140) : null, at: now, turn: s.turn, source, topicId: s.currentTopicId }
  return flash({ ...next, suggestions: keep([...kept, made], LIMITS.suggestions) }, sid)
}

function dropSuggestions(s: AtlasSnapshot, kind: AtlasSuggestionKind): AtlasSnapshot {
  return s.suggestions.some(x => x.kind === kind) ? { ...s, suggestions: s.suggestions.filter(x => x.kind !== kind) } : s
}

export function dismissSuggestion(s: AtlasSnapshot, sid: string, now: number): AtlasSnapshot {
  const hit = s.suggestions.find(x => x.id === sid)
  if (!hit) return s
  let next: AtlasSnapshot = { ...s, suggestions: s.suggestions.filter(x => x.id !== sid) }
  // "Not a detour": the excursion stays on the map as part of the main path.
  if (hit.kind === 'detour' && hit.topicId) {
    next = { ...next, topics: next.topics.map(t => (t.id === hit.topicId && t.kind === 'possible-detour' ? { ...t, kind: 'main' as const } : t)) }
  }
  return event(next, 'dismiss', `Dismissed ${hit.kind}: ${hit.text}`, now)
}

// ---------------------------------------------------------------- items

// Deterministic consequential-choice cues, matched as words (case-insensitive).
// Old decisions use exactly this rule on read; observation never writes intent.
const MAJOR_DECISION_CUE = /\b(?:architecture|schema|api|security|release|publish|delete|migrate|replace|rename|breaking|public|data|must|never|always|default|go\s+with)\b/i

export function autoDecisionWeight(text: string): 'major' | 'minor' {
  return MAJOR_DECISION_CUE.test(text) ? 'major' : 'minor'
}

export function decisionWeight(item: AtlasItem): 'major' | 'minor' {
  return item.weight ?? autoDecisionWeight(item.text)
}

export function toggleDecisionWeight(s: AtlasSnapshot, iid: string): AtlasSnapshot {
  const hit = s.decisions.find(item => item.id === iid)
  if (!hit) return s
  const weight = decisionWeight(hit) === 'major' ? 'minor' : 'major'
  return { ...s, decisions: s.decisions.map(item => item.id === iid ? { ...item, weight, weightBy: 'person' as const } : item) }
}

function addItem(s: AtlasSnapshot, list: 'decisions' | 'questions', text: string, source: AtlasSource, now: number): AtlasSnapshot {
  const body = clip(text, 160)
  if (!body) return s
  if (s[list].some(x => similar(x.text, body) && x.status !== 'resolved')) return s
  const [iid, next] = id(s, list === 'decisions' ? 'd' : 'q')
  const item: AtlasItem = { id: iid, text: body, at: now, turn: s.turn, topicId: s.currentTopicId, source, status: list === 'decisions' ? 'observed' : 'open', ...(list === 'decisions' ? { weight: autoDecisionWeight(body), weightBy: 'auto' as const } : {}) }
  const withItem = { ...next, [list]: keep([...next[list], item], LIMITS.items) } as AtlasSnapshot
  return flash(event(withItem, list === 'decisions' ? 'decision' : 'question', body, now), iid)
}

export function addDecision(s: AtlasSnapshot, text: string, source: AtlasSource, now: number): AtlasSnapshot {
  return addItem(s, 'decisions', text, source, now)
}

export function addQuestion(s: AtlasSnapshot, text: string, source: AtlasSource, now: number): AtlasSnapshot {
  return addItem(s, 'questions', text, source, now)
}

export function resolveQuestions(s: AtlasSnapshot, texts: string[], now: number): AtlasSnapshot {
  let next = s
  for (const text of texts) {
    const hit = next.questions.find(q => q.status === 'open' && similar(q.text, text))
    if (!hit) continue
    next = { ...next, questions: next.questions.map(q => (q.id === hit.id ? { ...q, status: 'resolved' as const } : q)) }
    next = event(next, 'resolved', hit.text, now)
  }
  return next
}

export function setItemStatus(s: AtlasSnapshot, iid: string, status: AtlasItem['status'] | 'drop', now: number): AtlasSnapshot {
  const list = iid.startsWith('d') ? 'decisions' : 'questions'
  const hit = s[list].find(x => x.id === iid)
  if (!hit) return s
  const items = status === 'drop' ? s[list].filter(x => x.id !== iid) : s[list].map(x => (x.id === iid ? { ...x, status } : x))
  let next = { ...s, [list]: items } as AtlasSnapshot
  if (status === 'settled' && s.detour) {
    // A decision settled during a detour is an accepted outcome of it.
    next = { ...next, detour: { ...s.detour, outcomes: [...s.detour.outcomes, hit.text].slice(-20) } }
  }
  if (status === 'excluded' && s.detour) {
    // Excluded material was explored during the detour and must not become an assumption.
    next = { ...next, detour: { ...s.detour, exclusions: [...s.detour.exclusions, hit.text].slice(-20) } }
  }
  const verb = status === 'settled' ? 'Settled' : status === 'excluded' ? 'Excluded' : status === 'resolved' ? 'Resolved' : status === 'open' ? 'Reopened' : status === 'drop' ? 'Dropped' : 'Marked'
  return event(next, status === 'resolved' ? 'resolved' : 'decision', `${verb}: ${hit.text}`, now)
}

// ---------------------------------------------------------------- topics (observation)

function addTopic(s: AtlasSnapshot, title: string, parentId: string | null, kind: AtlasTopic['kind'], source: AtlasSource, now: number): AtlasSnapshot {
  const [tid, next] = id(s, 't')
  const topic: AtlasTopic = { id: tid, title: clip(title, 60), parentId, kind, firstTurn: s.turn, lastTurn: s.turn, at: now, status: 'active', source }
  const topics = next.topics.map(t => (t.id === s.currentTopicId ? { ...t, status: 'left' as const } : t))
  const trimmed = keep([...topics, topic], LIMITS.topics)
  return flash(event({ ...next, topics: trimmed, currentTopicId: tid }, 'topic', `${kind === 'possible-detour' ? 'Possible detour' : 'Topic'}: ${topic.title}`, now), tid)
}

function moveTo(s: AtlasSnapshot, target: AtlasTopic, now: number): AtlasSnapshot {
  const topics = s.topics.map(t => {
    if (t.id === target.id) return { ...t, status: 'returned' as const, lastTurn: s.turn }
    if (t.id === s.currentTopicId) return { ...t, status: 'left' as const }
    return t
  })
  return flash(event({ ...s, topics, currentTopicId: target.id }, 'return', `Back to ${target.title}`, now), target.id)
}

function inDetourBranch(s: AtlasSnapshot, topic: AtlasTopic | null): boolean {
  return Boolean(topic && pathOf(s, topic.id).some(t => t.kind !== 'main'))
}

function returnTarget(s: AtlasSnapshot, title: string): AtlasTopic | null {
  const cur = currentTopic(s)
  if (title) {
    const named = [...s.topics].reverse().find(t => t.id !== cur?.id && similar(t.title, title))
    if (named) return named
  }
  if (s.detour?.topicId) {
    const departure = s.topics.find(t => t.id === s.detour?.topicId)
    if (departure?.parentId) return s.topics.find(t => t.id === departure.parentId) ?? null
  }
  // Leave the nearest excursion: return to the topic above the first non-main topic in the path.
  const chain = pathOf(s)
  const first = chain.findIndex(t => t.kind !== 'main')
  if (first > 0) return chain[first - 1] ?? null
  return chain.length > 1 ? (chain[chain.length - 2] ?? null) : null
}

export function observeTopic(s: AtlasSnapshot, title: string, shift: Shift | undefined, why: string | null, source: AtlasSource, now: number): AtlasSnapshot {
  const name = clip(title, 60)
  const cur = currentTopic(s)
  if (!cur) {
    if (!name) return s
    // A first topic that already reads as a side trip is still only a suggestion.
    if (shift === 'possible-detour' && !s.detour) return suggest(addTopic(s, name, null, 'possible-detour', source, now), 'detour', name, why, source, now)
    return addTopic(s, name, null, 'main', source, now)
  }
  const sameName = Boolean(name) && similar(cur.title, name)
  const move: Shift = shift ?? (sameName || !name ? 'same' : cur.parentId ? 'sibling' : 'subtopic')
  if (move === 'same' || (sameName && move !== 'return')) {
    const topics = s.topics.map(t => (t.id === cur.id ? { ...t, lastTurn: s.turn, title: name && move === 'same' ? name : t.title } : t))
    return { ...s, topics }
  }
  if (move === 'return') {
    const target = returnTarget(s, name)
    if (!target) return s
    let next = moveTo(s, target, now)
    if (s.detour) next = suggest(next, 'return', `Return to ${s.detour.departure.topic ?? s.detour.departure.goal ?? target.title}`, why ?? 'Claude observed the conversation going back', source, now)
    return next
  }
  if (!name) return s
  const branchKind: AtlasTopic['kind'] = inDetourBranch(s, cur) ? cur.kind : 'main'
  if (move === 'possible-detour') {
    if (s.detour) return addTopic(s, name, cur.id, 'detour', source, now)
    const next = addTopic(s, name, cur.id, 'possible-detour', source, now)
    return suggest(next, 'detour', name, why, source, now)
  }
  if (move === 'sibling') return addTopic(s, name, cur.parentId, cur.parentId ? branchKind : 'main', source, now)
  return addTopic(s, name, cur.id, branchKind, source, now)
}

// ---------------------------------------------------------------- Claude's report (observation)

export function observe(s: AtlasSnapshot, report: ObserveReport, now: number): AtlasSnapshot {
  let next = s
  if (report.topic || report.shift) next = observeTopic(next, report.topic ?? '', report.shift, report.why ?? null, 'claude', now)
  for (const d of report.decisions ?? []) next = addDecision(next, d, 'claude', now)
  if (report.resolved?.length) next = resolveQuestions(next, report.resolved, now)
  for (const q of report.questions ?? []) next = addQuestion(next, q, 'claude', now)
  if (report.next) next = suggest(next, 'next', report.next, null, 'claude', now)
  if (report.checkpoint) next = addCheckpoint(next, report.checkpoint, 'claude', null, now)
  if (report.goal) next = { ...next, detectedGoal: { text: clip(report.goal, 140), source: 'claude', at: now } }
  // A proposed goal is only ever a suggestion, and only while nothing is confirmed.
  if (report.goal && !next.goal) next = suggest(next, 'goal', report.goal, 'Proposed by Claude', 'claude', now)
  return report.topic || report.shift ? observeFocus(next) : next
}

// ---------------------------------------------------------------- prompt cues (observation)

const DETOUR_CUE = /\b(quick (detour|tangent|side ?quest)|side (question|quest|note)|tangent|unrelated(ly)?|btw|by the way|before (we|i) (continue|forget)|one sec|real quick)\b/i
const RETURN_CUE = /\b(back to (the )?(main|original|it|where)|let'?s get back|go back to|return(ing)? to (the )?(main|original|goal)|where were we|anyway,? (let'?s|back)|resume (the )?(main|original|work))\b/i
const DECISION_CUE = /\b(let'?s go with|we('ll| will) go with|i('ve| have)? decided|decision:|go with option|settled on|we('ll| will) use)\b/i

export function sentences(text: string): string[] {
  return (text.match(/[^.!?\n]+[.!?]*/g) ?? [text]).map(p => p.trim()).filter(Boolean)
}

type ReportMarker = { agent: string | null; taskId: string | null; summary: string }

function cleanMarkup(value: string): string {
  return value.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim()
}

// Engine-originated blocks are not prompts. Pasted content and image notices
// remain visible as compact typed-language stand-ins; notification blocks are
// consumed by delegation observation instead.
export function stripPromptMarkers(text: string): string {
  const lines = text.split(/\r?\n/)
  const kept: string[] = []
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index] ?? ''
    if (/^\s*<!--\s*reply\b[^>]*?-->\s*$/i.test(line)) {
      index++
      while (index < lines.length && (lines[index] ?? '').startsWith('>')) index++
      if ((lines[index] ?? '').trim() === '') index++
      index--
      continue
    }
    kept.push(line)
  }
  let body = kept.join('\n')
  body = body.replace(/<task-notification\b[^>]*>[\s\S]*?<\/task-notification>/gi, '')
  body = body.replace(/<agent-message\b[^>]*>[\s\S]*?<\/agent-message>/gi, '')
  // Blocks the app injects around the person's own text: never part of the title or the cues.
  body = body.replace(/<(system-reminder|local-command-caveat|cross-session-message)\b[^>]*>[\s\S]*?<\/\1>/gi, '')
  body = body.replace(/<pasted_content\b[^>]*>([\s\S]*?)<\/pasted_content>/gi, (_whole, inner: string) => {
    const count = inner.trim() ? inner.trim().split(/\r?\n/).length : 0
    return `pasted ${count} lines`
  })
  body = body.replace(/\[Image\s+#\d+\]/gi, 'image')
  return body.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim()
}

export function reportMarker(text: string): ReportMarker | null {
  const matches = [...text.matchAll(/<(task-notification|agent-message)\b([^>]*)>([\s\S]*?)<\/\1>/gi)]
  if (!matches.length) return null
  const last = matches[matches.length - 1]
  const attrs = last?.[2] ?? ''
  const fromMatch = /\bfrom\s*=\s*(?:["']([^"']+)["']|([^\s>]+))/i.exec(attrs)
  const from = fromMatch?.[1] ?? fromMatch?.[2] ?? null
  const body = last?.[3] ?? ''
  const taskId = cleanMarkup(body.match(/<task-id\b[^>]*>([\s\S]*?)<\/task-id>/i)?.[1] ?? '') || null
  const nestedSummary = body.match(/<summary\b[^>]*>([\s\S]*?)<\/summary>/i)?.[1]
  const nestedStatus = body.match(/<status\b[^>]*>([\s\S]*?)<\/status>/i)?.[1]
  const lineSummary = body.match(/^\s*summary\s*:\s*(.+)$/im)?.[1]
  const lineStatus = body.match(/^\s*status\s*:\s*(.+)$/im)?.[1]
  const summary = cleanMarkup(nestedSummary ?? lineSummary ?? nestedStatus ?? lineStatus ?? '') || (from ? `Report from ${from}` : 'Report received')
  return { agent: from, taskId, summary: clip(summary, 140) }
}

// The points a longer prompt makes, after its first sentence: list items as written,
// other lines split into sentences. The event keeps the full prompt separately.
// Heuristic, no model; at most 6.
export function promptBullets(text: string): string[] {
  const items: string[] = []
  let fenced = false
  for (const raw of text.split('\n')) {
    const line = raw.trim()
    if (/^(```|~~~)/.test(line)) {
      fenced = !fenced
      continue
    }
    if (fenced || !line) continue
    const bullet = /^(?:[-*•]|\d+[.)])\s+(.*)$/.exec(line)
    if (bullet) items.push(bullet[1] ?? '')
    else items.push(...sentences(line))
  }
  const kept = items
    .slice(1)
    .map(x => x.replace(/\s+/g, ' ').trim())
    .filter(x => x.length >= 4)
  const shown = kept.slice(0, 6).map(x => clip(x, 90))
  return kept.length > 6 ? [...shown, `+${kept.length - 6} more`] : shown
}

function sentenceWith(text: string, cue: RegExp): string {
  return sentences(text).find(p => cue.test(p)) ?? text
}

export function startTurn(s: AtlasSnapshot, text: string, now: number): AtlasSnapshot {
  const body = stripPromptMarkers(text)
  let next: AtlasSnapshot = { ...s, turn: s.turn + 1 }
  if (!body) return next
  next = event(next, 'prompt', body, now, promptBullets(body))
  if (body.startsWith('/') || body.startsWith('<')) return next
  if (!next.goal && !next.suggestions.some(x => x.kind === 'goal')) {
    const first = sentences(body)[0] ?? ''
    // Only the first sentence qualifies: 4 words, 16 characters, and not a
    // greeting/acknowledgment made solely of these words. Never fall back to body.
    const phraseWords = first.toLowerCase().match(/[\p{L}\p{N}]+/gu) ?? []
    const ackWords = new Set(['hi', 'hello', 'hey', 'ok', 'okay', 'thanks', 'thank', 'you', 'yes', 'yep', 'sure', 'please', 'do', 'it', 'go', 'ahead'])
    if (first.length >= 16 && phraseWords.length >= 4 && !phraseWords.every(word => ackWords.has(word)))
      next = suggest(next, 'goal', first, 'From your first request', 'cue', now)
  }
  if (DETOUR_CUE.test(body) && !next.detour) next = suggest(next, 'detour', clip(sentenceWith(body, DETOUR_CUE), 90), 'Your wording suggests a side trip', 'cue', now)
  if (RETURN_CUE.test(body) && next.detour) next = suggest(next, 'return', `Return to ${next.detour.departure.topic ?? next.detour.departure.goal ?? 'the main path'}`, 'Your wording suggests going back', 'cue', now)
  if (DECISION_CUE.test(body)) next = addDecision(next, sentenceWith(body, DECISION_CUE), 'cue', now)
  return next
}

// ---------------------------------------------------------------- activity & files (observation)

export function startActivity(s: AtlasSnapshot, a: Omit<AtlasActivity, 'state' | 'endedAt'>): AtlasSnapshot {
  return { ...s, activity: keep([...s.activity, { ...a, state: 'running', endedAt: null }], LIMITS.activity) }
}

export function endActivity(s: AtlasSnapshot, aid: string, state: 'done' | 'failed', now: number, label?: string): AtlasSnapshot {
  if (!s.activity.some(a => a.id === aid)) return s
  return { ...s, activity: s.activity.map(a => (a.id === aid ? { ...a, state, endedAt: now, label: label ?? a.label } : a)) }
}

function handoffBriefLabel(brief: string): string {
  if (!/\$[A-Za-z_][\w-]*[\\/]/.test(brief)) return brief
  return brief.replace(/\\/g, '/').split('/').at(-1) ?? brief
}

export function startHandoff(
  s: AtlasSnapshot,
  label: string,
  agent: string,
  brief: string | null,
  reportPath: string | null,
  now: number,
  reportFingerprint: string | null = null,
  taskId: string | null = null,
): AtlasSnapshot {
  const body = clip(label, 120) || agent || 'external agent'
  const [hid, next] = id(s, 'h')
  const handoff: AtlasHandoff = {
    id: hid,
    label: body,
    agent: clip(agent, 40) || 'agent',
    brief: brief ? clip(brief, 240) : null,
    reportPath: reportPath ? clip(reportPath, 400) : null,
    at: now,
    turn: s.turn,
    status: 'open',
    summary: null,
    tests: null,
    files: [],
    reportFingerprint,
    taskId: taskId ? clip(taskId, 120) : null,
  }
  const path = brief ? ` · ${handoffBriefLabel(brief)}` : ''
  return flash(event({ ...next, handoffs: keep([...next.handoffs, handoff], LIMITS.handoffs) }, 'handoff', `${body}${path}`, now), hid)
}

function handoffFor(s: AtlasSnapshot, agent?: string, idHint?: string): AtlasHandoff | null {
  const open = s.handoffs.filter(h => h.status === 'open')
  if (idHint) return open.find(h => h.id === idHint || h.taskId === idHint) ?? null
  if (agent) return [...open].reverse().find(h => h.agent.toLowerCase() === agent.toLowerCase()) ?? null
  return open.at(-1) ?? null
}

export function setHandoffTaskId(s: AtlasSnapshot, handoffId: string, taskId: string): AtlasSnapshot {
  const clean = clip(taskId, 120)
  if (!clean) return s
  return { ...s, handoffs: s.handoffs.map(h => h.id === handoffId ? { ...h, taskId: clean } : h) }
}

export function reportHandoff(s: AtlasSnapshot, summaryText: string, now: number, agent?: string, idHint?: string, tests: string | null = null, files: string[] = []): AtlasSnapshot {
  const hit = handoffFor(s, agent, idHint)
  const summary = clip(summaryText, 140) || 'Report received'
  const uniqueFiles = [...new Set(files.filter(Boolean))].slice(0, 20)
  const marked = hit
    ? s.handoffs.map(h => h.id === hit.id ? { ...h, status: 'reported' as const, summary, tests: tests ? clip(tests, 140) : h.tests, files: uniqueFiles.length ? uniqueFiles : h.files } : h)
    : s.handoffs
  const suffix = `${uniqueFiles.length ? ` · ${uniqueFiles.length} files` : ''}${tests ? ` · ${clip(tests, 100)}` : ''}`
  return event({ ...s, handoffs: marked }, 'report-back', `${summary}${suffix}`, now)
}

export function closeUnverifiedHandoffs(s: AtlasSnapshot, now: number): AtlasSnapshot {
  const hit = [...s.handoffs].reverse().find(h => h.status === 'open' && !h.reportPath && !h.taskId)
  if (!hit) return s
  const next: AtlasSnapshot = {
    ...s,
    handoffs: s.handoffs.map(h => h.id === hit.id ? { ...h, status: 'closed' as const, summary: 'back · unverified' } : h),
  }
  return event(next, 'report-back', `back · unverified${hit.label ? ` · ${hit.label}` : ''}`, now)
}

export function resolveRepoPath(root: string, path: string): string {
  const value = path.trim().replace(/\\/g, '/')
  if (!value) return ''
  if (value.startsWith('/') || /^[A-Za-z]:\//.test(value)) return value
  const base = root.replace(/\\/g, '/').replace(/\/+$/, '')
  return `${base}/${value.replace(/^\.\//, '')}`
}

export function touchFile(s: AtlasSnapshot, path: string, op: 'read' | 'write', now: number, source?: string): AtlasSnapshot {
  const resolved = resolveRepoPath(s.root, path)
  if (!resolved) return s
  const hit = s.files.find(f => f.path === resolved)
  const file: AtlasFile = hit
    ? { ...hit, reads: hit.reads + (op === 'read' ? 1 : 0), writes: hit.writes + (op === 'write' ? 1 : 0), lastOp: op, at: now, turn: s.turn, ...(source ? { source } : {}) }
    : { path: resolved, reads: op === 'read' ? 1 : 0, writes: op === 'write' ? 1 : 0, lastOp: op, at: now, turn: s.turn, ...(source ? { source } : {}) }
  const rest = s.files.filter(f => f.path !== resolved)
  return { ...s, files: keep([...rest, file], LIMITS.files) }
}

function writtenSince(s: AtlasSnapshot, at: number): string[] {
  return s.files.filter(f => f.writes > 0 && f.at > at).map(f => f.path).slice(-12)
}

// Checkpoints are evidence: a commit, a passing test run after edits, a milestone Claude
// reports, or a mark the person makes. None of them change the goal.
export function addCheckpoint(s: AtlasSnapshot, name: string, kind: AtlasCheckpoint['kind'], detail: string | null, now: number): AtlasSnapshot {
  const last = s.checkpoints[s.checkpoints.length - 1]
  const files = writtenSince(s, last?.at ?? 0)
  if (kind === 'tests' && files.length === 0) return s
  const [cid, next] = id(s, 'c')
  const label = clip(name, 60) || `checkpoint-${s.checkpoints.length + 1}`
  const cp: AtlasCheckpoint = { id: cid, name: label, at: now, turn: s.turn, kind, goal: s.goal?.text ?? null, topic: currentTopic(s)?.title ?? null, files, detail: detail ? clip(detail, 120) : null }
  const text = kind === 'tests' ? `${kindLabel(kind)} · ${detail ? clip(detail, 120) : 'command not recorded'}` : `${kindLabel(kind)}: ${label}`
  return flash(event({ ...next, checkpoints: keep([...next.checkpoints, cp], LIMITS.checkpoints) }, 'checkpoint', text, now), cid)
}

function kindLabel(kind: AtlasCheckpoint['kind']): string {
  return kind === 'marked' ? 'Marked' : kind === 'commit' ? 'Commit' : kind === 'tests' ? 'Tests passed' : 'Milestone'
}

// ---------------------------------------------------------------- intent (explicit only)

export function setGoal(s: AtlasSnapshot, text: string, source: AtlasSource, now: number): AtlasSnapshot {
  const body = clip(text, 140)
  if (!body) return s
  if (s.detour) return s
  const [gid, next] = id(s, 'g')
  const history = s.goal ? keep([...s.goalHistory, s.goal], LIMITS.history) : s.goalHistory
  const goal = { id: gid, text: body, at: now, turn: s.turn, source }
  return flash(event(dropSuggestions({ ...next, goal, goalHistory: history }, 'goal'), 'goal', body, now), gid)
}

export function setNextStep(s: AtlasSnapshot, text: string, now: number): AtlasSnapshot {
  const body = clip(text, 140)
  if (!body) return s
  return event(dropSuggestions({ ...s, nextStep: body }, 'next'), 'next', body, now)
}

export function mark(s: AtlasSnapshot, name: string, now: number): AtlasSnapshot {
  return addCheckpoint(s, name || `mark-${s.checkpoints.filter(c => c.kind === 'marked').length + 1}`, 'marked', null, now)
}

export function startDetour(s: AtlasSnapshot, reason: string, topicId: string | null, now: number): AtlasSnapshot {
  const body = clip(reason, 120)
  if (!body || s.detour) return s
  // A detour departs from the latest mark, creating one when none exists.
  let next = s
  let checkpoint = [...s.checkpoints].reverse().find(c => c.kind === 'marked') ?? null
  if (!checkpoint) {
    next = addCheckpoint(next, `before ${clip(body, 40)}`, 'marked', 'Created at detour departure', now)
    checkpoint = next.checkpoints[next.checkpoints.length - 1] ?? null
  }
  const departureTopic = topicId ? s.topics.find(t => t.id === topicId) : null
  const above = departureTopic?.parentId ? s.topics.find(t => t.id === departureTopic.parentId) : currentTopic(s)
  const [did, withId] = id(next, 'x')
  const detour: AtlasDetour = {
    id: did,
    reason: body,
    at: now,
    turn: s.turn,
    topicId,
    departure: {
      goal: s.goal?.text ?? null,
      topic: above?.title ?? null,
      nextStep: s.nextStep,
      checkpointId: checkpoint?.id ?? null,
      decisions: s.decisions.filter(d => d.status === 'settled').map(d => d.text).slice(-8),
    },
    outcomes: [],
    exclusions: [],
    status: 'active',
    endedAt: null,
  }
  const topics = withId.topics.map(t => (t.id === topicId ? { ...t, kind: 'detour' as const } : t))
  return flash(event(dropSuggestions({ ...withId, topics, detour }, 'detour'), 'detour', body, now), did)
}

const missing = (v: string | null | undefined) => (v && v.trim() ? v : 'not recorded')

// Deterministic return packet with what Claude needs to pick the main work back up.
export function returnPacket(s: AtlasSnapshot, d: AtlasDetour): string {
  const cp = s.checkpoints.find(c => c.id === d.departure.checkpointId)
  const observed = s.decisions.filter(x => x.status === 'observed' && x.at >= d.at).map(x => x.text)
  const list = (items: string[]) => (items.length ? items.map(x => `- ${x}`) : ['- not recorded'])
  return [
    'Conversation Atlas return packet (confirmed by the user)',
    `Original goal: ${missing(d.departure.goal)}`,
    `Returning to: ${missing(d.departure.topic)}`,
    `Detour: ${d.reason}`,
    `Return point: ${missing(cp?.name)}`,
    `Intended next step: ${missing(d.departure.nextStep)}`,
    'Settled decisions at departure:',
    ...list(d.departure.decisions),
    'Accepted detour outcomes:',
    ...list(d.outcomes),
    'Excluded material (explored, do not rely on it):',
    ...list(d.exclusions ?? []),
    'Observed during the detour, not confirmed (do not treat as settled):',
    ...list(observed.slice(-6)),
  ].join('\n')
}

export function returnFromDetour(s: AtlasSnapshot, now: number): AtlasSnapshot {
  const d = s.detour
  if (!d) return s
  const packet = returnPacket(s, d)
  const closed: AtlasDetour = { ...d, status: 'returned', endedAt: now }
  let next: AtlasSnapshot = { ...s, detour: null, detourHistory: keep([...s.detourHistory, closed], LIMITS.history), pendingContext: [...s.pendingContext, packet] }
  next = dropSuggestions(next, 'return')
  const target = d.topicId ? s.topics.find(t => t.id === d.topicId)?.parentId : null
  const topic = target ? next.topics.find(t => t.id === target) : null
  if (topic && next.currentTopicId !== topic.id) next = moveTo(next, topic, now)
  const topics = next.topics.map(t => (t.id === d.topicId ? { ...t, status: 'left' as const } : t))
  return event({ ...next, topics }, 'return', `Returned from detour: ${d.reason}`, now)
}

export function promoteDetour(s: AtlasSnapshot, now: number): AtlasSnapshot {
  const d = s.detour
  if (!d) return s
  const closed: AtlasDetour = { ...d, status: 'promoted', endedAt: now }
  const cleared: AtlasSnapshot = { ...s, detour: null, detourHistory: keep([...s.detourHistory, closed], LIMITS.history) }
  const promoted = setGoal(cleared, d.reason, 'person', now)
  const topics = promoted.topics.map(t => (t.id === d.topicId ? { ...t, kind: 'main' as const } : t))
  return event({ ...promoted, topics }, 'promote', `Detour became the goal: ${d.reason}`, now)
}

// /atlas decision: the person states a decision, so it is settled from the start.
export function recordDecision(s: AtlasSnapshot, text: string, why: string | null, now: number): AtlasSnapshot {
  const body = clip(why ? `${text} (because ${why})` : text, 160)
  if (!body) return s
  const added = addDecision(s, body, 'person', now)
  const item = added.decisions[added.decisions.length - 1]
  return item && item.text === body && item.status === 'observed' ? setItemStatus(added, item.id, 'settled', now) : added
}

// /atlas outcome and /atlas exclude record explicit detour findings.
export function addDetourFinding(s: AtlasSnapshot, kind: 'outcomes' | 'exclusions', text: string, now: number): AtlasSnapshot {
  const body = clip(text, 160)
  if (!s.detour || !body) return s
  const detour = { ...s.detour, [kind]: [...s.detour[kind], body].slice(-20) }
  return event({ ...s, detour }, 'decision', `${kind === 'outcomes' ? 'Outcome' : 'Excluded'}: ${body}`, now)
}

export function setRecall(s: AtlasSnapshot, recall: AtlasRecall[]): AtlasSnapshot {
  return { ...s, recall: recall.filter(r => r.sessionId !== s.sessionId).slice(0, 12) }
}

export function hasReplaceableContent(s: AtlasSnapshot): boolean {
  return Boolean(
    s.goal ||
    s.nextStep ||
    s.detour ||
    s.topics.length ||
    s.decisions.length ||
    s.questions.length ||
    s.checkpoints.length ||
    s.files.length ||
    s.activity.length,
  )
}

function highestIdSequence(value: unknown): number {
  if (Array.isArray(value)) return value.reduce((max, item) => Math.max(max, highestIdSequence(item)), 0)
  if (!value || typeof value !== 'object') return 0
  let max = 0
  for (const [key, child] of Object.entries(value)) {
    if (key === 'id' && typeof child === 'string') {
      const match = /(\d+)$/.exec(child)
      if (match) max = Math.max(max, Number(match[1]))
    } else {
      max = Math.max(max, highestIdSequence(child))
    }
  }
  return max
}

export function recoverFull(
  current: AtlasSnapshot,
  source: { id: string; sessionId: string; snapshot: unknown },
  now: number,
): AtlasSnapshot {
  if (snapshotError(source.snapshot)) return current
  const loaded = upgrade(hydrate(source.snapshot, current.sessionId, current.root, now))
  const seq = Math.max(current.seq, loaded.seq, highestIdSequence(loaded))
  const adopted = [...new Set([...loaded.adopted, source.id])]
  const next: AtlasSnapshot = {
    ...loaded,
    sessionId: current.sessionId,
    root: current.root,
    fresh: [],
    recall: current.recall,
    adopted,
    pendingContext: [],
    seq,
  }
  return event(next, 'resume', `Loaded full map from session ${source.sessionId.slice(0, 8)}`, now)
}

// Resume an earlier Atlas session: its goal, next step and settled
// decisions become yours because you pressed Resume; a detour it was on comes back
// as a suggestion, so you choose whether to re-enter it.
export function adoptRecall(s: AtlasSnapshot, rid: string, now: number): AtlasSnapshot {
  const r = s.recall.find(x => x.id === rid)
  if (!r || s.adopted.includes(rid)) return s
  let next: AtlasSnapshot = { ...s, adopted: [...s.adopted, rid] }
  if (r.goal && !next.detour) next = setGoal(next, r.goal, 'person', now)
  if (r.nextStep) next = setNextStep(next, r.nextStep, now)
  for (const d of r.decisions.slice(-8)) {
    const added = addDecision(next, d, 'person', now)
    const item = added.decisions[added.decisions.length - 1]
    next = item && item !== next.decisions[next.decisions.length - 1] ? setItemStatus(added, item.id, 'settled', now) : added
  }
  if (r.detour && !next.detour) next = suggest(next, 'detour', r.detour, 'The earlier session was on this detour', 'engine', now)
  return event(dropSuggestions(next, 'resume'), 'resume', `Resumed session ${r.sessionId.slice(0, 8)}: ${r.goal ?? 'no goal'}`, now)
}

export function confirmSuggestion(s: AtlasSnapshot, sid: string, now: number): AtlasSnapshot {
  const hit = s.suggestions.find(x => x.id === sid)
  if (!hit) return s
  const rest: AtlasSnapshot = { ...s, suggestions: s.suggestions.filter(x => x.id !== sid) }
  if (hit.kind === 'goal') return setGoal(rest, hit.text, 'person', now)
  if (hit.kind === 'next') return setNextStep(rest, hit.text, now)
  if (hit.kind === 'detour') return startDetour(rest, hit.text, hit.topicId, now)
  if (hit.kind === 'return') return returnFromDetour(rest, now)
  if (hit.kind === 'resume') {
    const [goal, step] = hit.text.split(' → next: ')
    let next = rest.goal ? rest : setGoal(rest, goal ?? hit.text, 'person', now)
    if (step) next = setNextStep(next, step, now)
    return event(next, 'resume', hit.text, now)
  }
  return rest
}

// Offered once in a new session of the same project: the last session's goal and next step.
export function offerResume(s: AtlasSnapshot, previous: { goal: string | null; nextStep: string | null; detour: string | null } | null, now: number): AtlasSnapshot {
  if (!previous?.goal || s.goal) return s
  const text = previous.nextStep ? `${previous.goal} → next: ${previous.nextStep}` : previous.goal
  return suggest(s, 'resume', text, previous.detour ? `Last session ended inside a detour: ${previous.detour}` : 'Where the last session in this project left off', 'engine', now)
}

export function takeContext(s: AtlasSnapshot): [string[], AtlasSnapshot] {
  return s.pendingContext.length ? [s.pendingContext, { ...s, pendingContext: [] }] : [[], s]
}

// What to pick up next, most specific first. Every line says where it came from.
export function resumeHint(s: AtlasSnapshot): { text: string; source: string; suggestionId?: string } | null {
  if (s.detour) return { text: `Finish "${s.detour.reason}", then return to ${s.detour.departure.topic ?? s.detour.departure.goal ?? 'the main path'}`, source: 'detour' }
  if (s.nextStep) return { text: s.nextStep, source: 'pinned' }
  const next = [...s.suggestions].reverse().find(x => x.kind === 'next')
  if (next) return { text: next.text, source: 'suggested', suggestionId: next.id }
  const open = openQuestions(s)
  const lastQ = open[open.length - 1]
  if (lastQ) return { text: `Answer: ${lastQ.text}`, source: 'open question' }
  const lastWrite = [...s.files].reverse().find(f => f.writes > 0)
  if (lastWrite) return { text: `Continue in ${lastWrite.path.split('/').pop()}`, source: 'last edit' }
  return null
}

// One short line Claude reads beside a prompt, only while the person has confirmed intent.
export function intentLine(s: AtlasSnapshot): string | null {
  if (!s.goal && !s.detour && !s.nextStep) return null
  const parts = [
    s.goal ? `goal "${s.goal.text}"` : null,
    s.detour ? `on a detour "${s.detour.reason}" (returns to ${s.detour.departure.topic ?? 'the main path'})` : null,
    s.nextStep ? `next step "${s.nextStep}"` : null,
  ].filter(Boolean)
  return `Conversation Atlas, confirmed by the user: ${parts.join('; ')}.`
}

export function summary(s: AtlasSnapshot): { goal: string | null; nextStep: string | null; detour: string | null; topic: string | null; at: number } {
  return { goal: s.goal?.text ?? null, nextStep: s.nextStep ?? resumeHint(s)?.text ?? null, detour: s.detour?.reason ?? null, topic: currentTopic(s)?.title ?? null, at: s.events[s.events.length - 1]?.at ?? s.startedAt }
}

files.hooks/scan.ts:
// Mapping a conversation that already happened: a session Atlas joins late (installed or
// reloaded mid-thread, resumed with no save). Pure: the hooks module reads the rows with
// `$.session.messages()` and, when asked, one `$.model.fork` reply.
//
//   replay      free; prompts, wording cues, files, tests, commits, open questions
//   claudeMap   one forked request; topics, decisions, open questions, next step
// Both write observations only, like everything else outside the confirm functions.

import type { AtlasSnapshot } from '../types'
import { askedQuestions, classify, isTestCommand } from './activity'
import { addCheckpoint, addQuestion, clip, observe, type ObserveReport, sentences, type Shift, startTurn, touchFile } from './model'

export type ScanRow = {
  role: 'user' | 'assistant'
  text: string
  toolUses?: readonly { tool: string; input: Record<string, unknown>; result?: unknown; isError?: true }[]
}

// Engine rows the person did not type: reminders, command echoes, task notifications.
function typed(text: string): boolean {
  const t = text.trim()
  return t.length > 0 && !t.startsWith('<') && !t.startsWith('[Request interrupted')
}

export function replay(s: AtlasSnapshot, rows: readonly ScanRow[], now: number): AtlasSnapshot {
  let next = s
  let lastAnswer = ''
  for (const row of rows) {
    if (row.role === 'user') {
      if (typed(row.text)) next = startTurn(next, row.text, now)
      continue
    }
    if (row.text.trim()) lastAnswer = row.text
    for (const use of row.toolUses ?? []) {
      const c = classify(String(use.tool), use.input)
      if (!c || use.isError) continue
      for (const f of c.files) next = touchFile(next, f.path, f.op, now)
      if (c.isTest || (use.tool === 'Bash' && isTestCommand(String(use.input.command ?? '')))) next = addCheckpoint(next, 'Tests passed', 'tests', c.label.replace(/^Tests: /, ''), now)
      const commit = (use.result as { gitOperation?: { commit?: { sha?: string } } } | undefined)?.gitOperation?.commit
      if (commit?.sha) next = addCheckpoint(next, `Commit ${commit.sha.slice(0, 7)}`, 'commit', null, now)
      // A question Claude asked earlier and the person answered is history, not an open item.
      if (use.tool === 'AskUserQuestion' && use.result === undefined) for (const q of askedQuestions(use.input)) next = addQuestion(next, q, 'claude', now)
    }
  }
  const tail = (lastAnswer.trim().split(/\n\s*\n/).pop() ?? '').trim()
  const lastRow = rows[rows.length - 1]
  if (lastRow?.role === 'assistant' && tail.endsWith('?')) {
    const q = sentences(tail).filter(x => x.endsWith('?')).pop()
    if (q) next = addQuestion(next, q, 'engine', now)
  }
  return next
}

export const MAP_PROMPT = `Map this conversation so far for the user's Conversation Atlas pane. Reply with JSON only, no prose, no tool calls:
{"goal": "the user's main goal in their own words, or null",
 "topics": [{"topic": "at most 6 words", "shift": "subtopic | sibling | possible-detour | return", "why": "one line, only for possible-detour or return"}],
 "decisions": ["conclusions actually reached"],
 "questions": ["questions still open now"],
 "resolved": ["questions that were open and got answered"],
 "next": "the most useful next step to resume from"}
Topics in the order they happened, at most 12; the first one's shift is ignored. At most 8 decisions, 5 open questions. Observations only: do not decide anything for the user.`

const SHIFTS: Shift[] = ['same', 'subtopic', 'sibling', 'possible-detour', 'return']

function list(v: unknown, max: number): string[] {
  return Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string').map(x => clip(x, 160)).filter(Boolean).slice(0, max) : []
}

// Parses the fork's reply; tolerant of a fenced block or text around the JSON.
export function parseMap(text: string): { topics: { topic: string; shift: Shift; why: string | null }[]; rest: ObserveReport } | null {
  const start = text.indexOf('{')
  const end = text.lastIndexOf('}')
  if (start < 0 || end <= start) return null
  let raw: unknown
  try {
    raw = JSON.parse(text.slice(start, end + 1))
  } catch {
    return null
  }
  if (!raw || typeof raw !== 'object') return null
  const v = raw as Record<string, unknown>
  const topics = (Array.isArray(v.topics) ? v.topics : [])
    .filter((t): t is Record<string, unknown> => Boolean(t) && typeof t === 'object')
    .map(t => ({
      topic: clip(t.topic, 60),
      shift: (SHIFTS.includes(t.shift as Shift) ? t.shift : 'sibling') as Shift,
      why: clip(t.why, 140) || null,
    }))
    .filter(t => t.topic)
    .slice(0, 12)
  const rest: ObserveReport = {
    goal: clip(v.goal, 140) || undefined,
    decisions: list(v.decisions, 8),
    questions: list(v.questions, 5),
    resolved: list(v.resolved, 8),
    next: clip(v.next, 140) || undefined,
  }
  return { topics, rest }
}

export function applyMap(s: AtlasSnapshot, map: NonNullable<ReturnType<typeof parseMap>>, now: number): AtlasSnapshot {
  let next = s
  for (const t of map.topics) next = observe(next, { topic: t.topic, shift: t.shift, why: t.why ?? undefined }, now)
  return observe(next, map.rest, now)
}

